/** Hex color interpolation utilities */

export const hexToRgb = (hex: string): [number, number, number] => {
  const h = hex.replace('#', '');
  return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
};

export const rgbToHex = (r: number, g: number, b: number): string =>
  '#' + [r, g, b].map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');

export const lerpHexColor = (a: string, b: string, t: number): string => {
  const [ar, ag, ab] = hexToRgb(a);
  const [br, bg, bb] = hexToRgb(b);
  return rgbToHex(ar + (br - ar) * t, ag + (bg - ag) * t, ab + (bb - ab) * t);
};

/** Convert an ArrayBuffer to a base64-encoded string */
export const arrayBufferToBase64 = (buffer: ArrayBuffer): string => {
  const bytes = new Uint8Array(buffer);
  const CHUNK_SIZE = 0x8000;
  let index = 0;
  const length = bytes.length;
  let result = '';
  while (index < length) {
    const chunk = bytes.slice(index, Math.min(index + CHUNK_SIZE, length));
    result += String.fromCharCode.apply(null, Array.from(chunk));
    index += CHUNK_SIZE;
  }
  return window.btoa(result);
};

/**
 * Build a glyph atlas canvas: each character rendered into a `size x size` cell,
 * laid out horizontally. Returns the canvas (callers wrap it in a texture as needed).
 */
export const buildGlyphCanvas = (chars: string, cellSize: number = 64): HTMLCanvasElement => {
  const canvas = document.createElement('canvas');
  canvas.width = cellSize * Math.max(chars.length, 1);
  canvas.height = cellSize;

  const ctx = canvas.getContext('2d');
  if (!ctx) return canvas; // degenerate fallback

  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.font = `bold ${cellSize * 0.8}px "Courier New", monospace`;
  ctx.fillStyle = '#ffffff';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  for (let i = 0; i < chars.length; i++) {
    ctx.fillText(chars[i], i * cellSize + cellSize / 2, cellSize / 2);
  }

  return canvas;
};

import type { GradientStop } from '../types';
import { uid } from './uid';

/** Clone template stops with fresh IDs */
export const cloneStops = (stops: GradientStop[]): GradientStop[] =>
  stops.map(s => ({ ...s, id: uid() }));

/**
 * Build a 256x1 gradient LUT canvas from an array of gradient stops.
 * Reusable across offlineRenderer, previewRenderer, and the studio pipeline.
 */
export const buildGradientCanvas = (
  stops: GradientStop[],
  width: number = 256
): HTMLCanvasElement => {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = 1;
  const ctx = canvas.getContext('2d')!;

  const grad = ctx.createLinearGradient(0, 0, width, 0);
  const sorted = [...stops].sort((a, b) => a.position - b.position);

  if (sorted.length > 0) {
    if (sorted[0].position > 0) grad.addColorStop(0, sorted[0].color);
    sorted.forEach(s => grad.addColorStop(Math.max(0, Math.min(1, s.position)), s.color));
    if (sorted[sorted.length - 1].position < 1) grad.addColorStop(1, sorted[sorted.length - 1].color);
  } else {
    grad.addColorStop(0, '#000000');
    grad.addColorStop(1, '#ffffff');
  }

  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, 1);
  return canvas;
};

export { hexToRgb, rgbToHex, lerpHexColor } from './color';
export { uid } from './uid';
export { arrayBufferToBase64 } from './encoding';
export { cloneStops, buildGradientCanvas } from './gradient';
export { buildGlyphCanvas } from './glyphAtlas';

/** Generate a unique stop/element ID */
export const uid = (): string =>
  typeof crypto !== 'undefined' && crypto.randomUUID
    ? crypto.randomUUID()
    : `s-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

import * as THREE from 'three';
import { createShaderMaterial } from './createShaderMaterial';
import { FULLSCREEN_VERTEX } from './vertex';

/**
 * Pass 2: Colorize & Stylize
 *
 * Input:  FBO A (effect pass output)
 * Output: FBO B
 *
 * Applies color grading (contrast, brightness, saturation, shadows, highlights,
 * temperature, tint), gradient mapping, and ASCII / Dither stylization.
 */

const COLORIZE_FRAGMENT = `
  uniform sampler2D uVideo;
  uniform sampler2D uGlyphs;
  uniform sampler2D uColorMap;
  uniform float uGradientOffset;

  uniform vec3 uPrimaryColor;
  uniform vec3 uSecondaryColor;
  uniform vec2 uGridSize;
  uniform float uNumGlyphs;
  uniform int uColorMode;
  uniform int uEffectType;   // 0: ASCII, 1: Dither, -1: None
  uniform int uDitherType;
  uniform float uPixelSize;
  uniform float uDitherSpread;
  uniform float uColorDepth;
  uniform float uCharSpacing;
  uniform float uAsciiLuminance;
  uniform float uAsciiWeight;
  uniform vec2 uResolution;
  uniform float uAspect;

  uniform float uContrast;
  uniform float uBrightness;
  uniform float uSaturation;
  uniform float uShadows;
  uniform float uHighlights;
  uniform float uTemperature;
  uniform float uTint;

  uniform float uUseSourceAsBg;

  varying vec2 vUv;

  float getLuminance(vec3 color) {
    return dot(color, vec3(0.299, 0.587, 0.114));
  }

  float errorDiffusionLook(vec2 p) {
      vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
      p3 += dot(p3, p3.yzx + 33.33);
      float noise = fract((p3.x + p3.y) * p3.z);
      float phi = 1.61803398875;
      return fract(noise + dot(p, vec2(1.0, phi)));
  }

  float bayer4(vec2 p) {
    vec2 m = mod(p, 4.0);
    float matrix[16];
    matrix[0]=0.0; matrix[1]=8.0; matrix[2]=2.0; matrix[3]=10.0;
    matrix[4]=12.0; matrix[5]=4.0; matrix[6]=14.0; matrix[7]=6.0;
    matrix[8]=3.0; matrix[9]=11.0; matrix[10]=1.0; matrix[11]=9.0;
    matrix[12]=15.0; matrix[13]=7.0; matrix[14]=13.0; matrix[15]=5.0;
    return matrix[int(m.y) * 4 + int(m.x)] / 16.0;
  }

  float bayer8(vec2 p) {
    vec2 m = mod(p, 8.0);
    int x = int(m.x); int y = int(m.y);
    float mat[64];
    mat[0]=0.0; mat[1]=32.0; mat[2]=8.0; mat[3]=40.0; mat[4]=2.0; mat[5]=34.0; mat[6]=10.0; mat[7]=42.0;
    mat[8]=48.0; mat[9]=16.0; mat[10]=56.0; mat[11]=24.0; mat[12]=50.0; mat[13]=18.0; mat[14]=58.0; mat[15]=26.0;
    mat[16]=12.0; mat[17]=44.0; mat[18]=4.0; mat[19]=36.0; mat[20]=14.0; mat[21]=46.0; mat[22]=6.0; mat[23]=38.0;
    mat[24]=60.0; mat[25]=28.0; mat[26]=52.0; mat[27]=20.0; mat[28]=62.0; mat[29]=30.0; mat[30]=54.0; mat[31]=22.0;
    mat[32]=3.0; mat[33]=35.0; mat[34]=11.0; mat[35]=43.0; mat[36]=1.0; mat[37]=33.0; mat[38]=9.0; mat[39]=41.0;
    mat[40]=51.0; mat[41]=19.0; mat[42]=59.0; mat[43]=27.0; mat[44]=49.0; mat[45]=17.0; mat[46]=57.0; mat[47]=25.0;
    mat[48]=15.0; mat[49]=47.0; mat[50]=7.0; mat[51]=39.0; mat[52]=13.0; mat[53]=45.0; mat[54]=5.0; mat[55]=37.0;
    mat[56]=63.0; mat[57]=31.0; mat[58]=55.0; mat[59]=23.0; mat[60]=61.0; mat[61]=29.0; mat[62]=53.0; mat[63]=21.0;
    return mat[y * 8 + x] / 64.0;
  }

  void main() {
    vec2 baseUv = vUv;

    vec2 virtualRes = vec2(1280.0, 1280.0 / uAspect);
    vec2 dRes = virtualRes / max(uPixelSize, 1.0);
    vec2 samplingUv = baseUv;

    if (uEffectType == 1 && uPixelSize > 1.0) {
      samplingUv = (floor(samplingUv * dRes) + 0.5) / dRes;
    }

    vec3 rawColor = texture2D(uVideo, samplingUv).rgb;
    vec3 originalSample = texture2D(uVideo, baseUv).rgb;

    // --- Color Grading Pipeline ---
    // 1. Contrast & Brightness
    rawColor = (rawColor - 0.5) * uContrast + 0.5 + uBrightness;
    originalSample = (originalSample - 0.5) * uContrast + 0.5 + uBrightness;

    // 2. Shadows & Highlights
    float lum = getLuminance(rawColor);
    rawColor += uShadows * (1.0 - smoothstep(0.0, 0.5, lum)) * 0.15;
    rawColor += uHighlights * smoothstep(0.5, 1.0, lum) * 0.15;

    // 3. Saturation
    rawColor = mix(vec3(lum), rawColor, uSaturation);

    // 4. Temperature & Tint
    rawColor.r += uTemperature * 0.05;
    rawColor.b -= uTemperature * 0.05;
    rawColor.g -= uTint * 0.05;
    rawColor.r += uTint * 0.02;
    rawColor.b += uTint * 0.02;

    rawColor = clamp(rawColor, 0.0, 1.0);

    vec3 targetColor = rawColor;

    float workingLum = getLuminance(targetColor);

    if (uColorMode == 2) {
      float lookup = fract(workingLum + uGradientOffset);
      targetColor = texture2D(uColorMap, vec2(lookup, 0.5)).rgb;
    }

    vec3 finalColor = targetColor;

    vec3 bgColor = uSecondaryColor;
    if (uUseSourceAsBg > 0.5) {
      bgColor = originalSample;
    }

    // --- ASCII Stylization ---
    if (uEffectType == 0) {
      vec2 gridUv = floor(baseUv * uGridSize) / uGridSize;
      vec2 centerUv = gridUv + (0.5 / uGridSize);
      vec2 cellHalf = 0.5 / uGridSize;
      vec3 centerColor = (texture2D(uVideo, centerUv).rgb
        + texture2D(uVideo, centerUv + vec2(cellHalf.x, 0.0)).rgb
        + texture2D(uVideo, centerUv + vec2(0.0, cellHalf.y)).rgb
        + texture2D(uVideo, centerUv - vec2(cellHalf.x, 0.0)).rgb
        + texture2D(uVideo, centerUv - vec2(0.0, cellHalf.y)).rgb) * 0.2;
      centerColor = (centerColor - 0.5) * uContrast + 0.5 + uBrightness;

      // Shadows & Highlights on centerColor
      float cLum = getLuminance(centerColor);
      centerColor += uShadows * (1.0 - smoothstep(0.0, 0.5, cLum)) * 0.15;
      centerColor += uHighlights * smoothstep(0.5, 1.0, cLum) * 0.15;

      // Saturation
      centerColor = mix(vec3(cLum), centerColor, uSaturation);

      // Temperature & Tint
      centerColor.r += uTemperature * 0.05;
      centerColor.b -= uTemperature * 0.05;
      centerColor.g -= uTint * 0.05;
      centerColor.r += uTint * 0.02;
      centerColor.b += uTint * 0.02;

      centerColor = clamp(centerColor, 0.0, 1.0);

      float cellLum = getLuminance(centerColor);
      cellLum = pow(cellLum, 1.0 / max(uAsciiLuminance, 0.01));
      cellLum = clamp(cellLum, 0.0, 0.999);

      float glyphIndex = floor(cellLum * uNumGlyphs);
      vec2 cellUv = fract(baseUv * uGridSize);
      vec2 centeredCellUv = (cellUv - 0.5) / uCharSpacing + 0.5;

      float mask = 0.0;
      if (centeredCellUv.x >= 0.0 && centeredCellUv.x <= 1.0 && centeredCellUv.y >= 0.0 && centeredCellUv.y <= 1.0) {
        float glyphWidth = 1.0 / uNumGlyphs;
        vec2 glyphUv = vec2((centeredCellUv.x + glyphIndex) * glyphWidth, centeredCellUv.y);
        mask = texture2D(uGlyphs, glyphUv).r;
        mask = clamp((mask - 0.5) * uAsciiWeight + 0.5, 0.0, 1.0);
      }
      vec3 cellTargetColor = centerColor;
      if (uColorMode == 2) {
        float lookup = fract(cellLum + uGradientOffset);
        cellTargetColor = texture2D(uColorMap, vec2(lookup, 0.5)).rgb;
      }
      finalColor = mix(bgColor, cellTargetColor, mask);

    // --- Dither Stylization ---
    } else if (uEffectType == 1) {
      vec2 dCoord = floor(baseUv * dRes);
      float dThreshold;
      if (uDitherType <= 1) dThreshold = bayer4(dCoord);
      else if (uDitherType <= 3) dThreshold = bayer8(dCoord);
      else dThreshold = errorDiffusionLook(dCoord);

      float result = workingLum + (dThreshold - 0.5) * uDitherSpread;
      float ditherBit = clamp(floor(result * uColorDepth + 0.5) / max(uColorDepth, 1.0), 0.0, 1.0);
      finalColor = mix(bgColor, targetColor, ditherBit);
    }

    gl_FragColor = vec4(finalColor, 1.0);
  }
`;

const ColorizeMaterial = createShaderMaterial(
  {
    uVideo: new THREE.Texture(),
    uGlyphs: new THREE.Texture(),
    uColorMap: new THREE.Texture(),
    uGradientOffset: 0.0,
    uPrimaryColor: new THREE.Color('#ffffff'),
    uSecondaryColor: new THREE.Color('#000000'),
    uGridSize: new THREE.Vector2(80, 45),
    uNumGlyphs: 10.0,
    uColorMode: 1,
    uEffectType: -1,
    uDitherType: 0,
    uPixelSize: 1.0,
    uDitherSpread: 1.0,
    uColorDepth: 4.0,
    uCharSpacing: 1.0,
    uAsciiLuminance: 1.0,
    uAsciiWeight: 1.0,
    uResolution: new THREE.Vector2(1, 1),
    uAspect: 1.0,
    uContrast: 1.0,
    uBrightness: 0.0,
    uSaturation: 1.0,
    uShadows: 0.0,
    uHighlights: 0.0,
    uTemperature: 0.0,
    uTint: 0.0,
    uUseSourceAsBg: 0.0,
  },
  FULLSCREEN_VERTEX,
  COLORIZE_FRAGMENT
);

export default ColorizeMaterial;
export { COLORIZE_FRAGMENT };

import * as THREE from 'three';

/**
 * Lightweight replacement for @react-three/drei's shaderMaterial.
 * Creates a THREE.ShaderMaterial subclass with automatic uniform getters/setters.
 */
export function createShaderMaterial(
  uniforms: { [key: string]: any },
  vertexShader: string,
  fragmentShader: string
) {
  return class extends THREE.ShaderMaterial {
    constructor() {
      super({
        uniforms: Object.entries(uniforms).reduce((acc, [name, value]) => {
          const uniform = { [name]: { value } };
          return { ...acc, ...THREE.UniformsUtils.clone(uniform) };
        }, {}),
        vertexShader,
        fragmentShader,
      });

      Object.keys(uniforms).forEach((name) => {
        Object.defineProperty(this, name, {
          get: () => this.uniforms[name].value,
          set: (v) => (this.uniforms[name].value = v),
        });
      });
    }
  };
}

import * as THREE from 'three';
import { createShaderMaterial } from './createShaderMaterial';
import { FULLSCREEN_VERTEX } from './vertex';

/**
 * Pass 3: Finishing
 *
 * Input:  FBO B (colorize pass output)
 * Output: Screen
 *
 * Applies zoom/pan, film grain, vignette, and flicker.
 */

const FINISHING_FRAGMENT = `
  uniform sampler2D tDiffuse;
  uniform float uTime;
  uniform float uZoom;
  uniform vec2 uPan;
  uniform float uGrain;
  uniform float uVignette;
  uniform float uFlicker;

  varying vec2 vUv;

  float generateNoise(vec2 uv, float time) {
    vec2 animatedUV = uv + fract(time);
    return fract(sin(dot(animatedUV, vec2(12.9898, 78.233))) * 43758.5453);
  }

  vec3 blendOverlay(vec3 base, vec3 blend) {
    vec3 limit = step(0.5, base);
    return mix(
      2.0 * base * blend,
      1.0 - 2.0 * (1.0 - base) * (1.0 - blend),
      limit
    );
  }

  void main() {
    // Zoom & Pan
    vec2 baseUv = (vUv - 0.5 - uPan) / uZoom + 0.5;

    if (baseUv.x < 0.0 || baseUv.x > 1.0 || baseUv.y < 0.0 || baseUv.y > 1.0) {
      gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0);
      return;
    }

    vec3 finalColor = texture2D(tDiffuse, baseUv).rgb;

    // Film Grain (Overlay blend)
    if (uGrain > 0.001) {
      float noiseValue = generateNoise(baseUv, uTime);
      vec3 grainColor = vec3(noiseValue);
      vec3 overlayed = blendOverlay(finalColor, grainColor);
      finalColor = mix(finalColor, overlayed, uGrain);
    }

    // Vignette
    if (uVignette > 0.001) {
      vec2 centeredUv = vUv - 0.5;
      float dist = length(centeredUv);
      float vig = 1.0 - smoothstep(0.3, 1.0, dist) * uVignette;
      finalColor *= vig;
    }

    // Flicker
    if (uFlicker > 0.01) {
      float breathing = 1.0 + (sin(uTime * 4.0) * 0.02 + sin(uTime * 1.5) * 0.01) * uFlicker;
      finalColor *= breathing;
    }

    gl_FragColor = vec4(finalColor, 1.0);
  }
`;

const FinishingMaterial = createShaderMaterial(
  {
    tDiffuse: new THREE.Texture(),
    uTime: 0.0,
    uZoom: 1.0,
    uPan: new THREE.Vector2(0, 0),
    uGrain: 0.0,
    uVignette: 0.0,
    uFlicker: 0.0,
  },
  FULLSCREEN_VERTEX,
  FINISHING_FRAGMENT
);

export default FinishingMaterial;
export { FINISHING_FRAGMENT };

export { createShaderMaterial } from './createShaderMaterial';
export { FULLSCREEN_VERTEX } from './vertex';
export { default as ColorizeMaterial, COLORIZE_FRAGMENT } from './colorizeMaterial';
export { default as FinishingMaterial, FINISHING_FRAGMENT } from './finishingMaterial';

export const FULLSCREEN_VERTEX = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

import type * as THREE from 'three';

export interface FlowMediaItem {
  id: string;
  base64: string;
  mimeType: string;
  dataUrl: string;
  type: 'image' | 'video';
  name: string;
}

export type ColorMode = 1 | 2; // 1: Live/Original, 2: Gradient Map
export type DitherType = 0 | 1 | 2 | 3 | 4; 

export interface AsciiPreset {
  id: string;
  name: string;
  chars: string;
  asciiFontSize: number;
  spacing: number;
}

export interface GradientStop {
  id: string;
  color: string;
  position: number;
}

export interface GradientTemplate {
  id: string;
  name: string;
  stops: GradientStop[];
}

export interface AsciiParams {
  chars: string;
  asciiFontSize: number;
  charSpacing: number;
  asciiLuminance: number;
  asciiWeight: number;
  useSourceAsBg: boolean;
  secondaryColor: string;
  fps: number;
}

export interface DitherParams {
  pixelSize: number;
  colorDepth: number;
  ditherType: DitherType;
  ditherSpread: number;
  useSourceAsBg: boolean;
  secondaryColor: string;
  fps: number;
}

export interface StudioParams {
  presetId: string | null;
  asciiPresetId: string | null;
  gradientId: string | null;
  gradientStops: GradientStop[];

  ascii: AsciiParams;
  dither: DitherParams;

  contrast: number;
  brightness: number;
  saturation: number;
  shadows: number;
  highlights: number;
  temperature: number;
  tint: number;
  grain: number;
  vignette: number;

  zoom: number;
  pan: [number, number];

  colorMode: ColorMode;
  primaryColor: string;

  gradientAnimated: boolean;
  gradientSpeed: number;
  gradientOffset: number;
  flicker: number;

  bloomIntensity: number;
  bloomThreshold: number;
  bloomSmoothing: number;
  bloomRadius: number;
}

export type ShaderParameterValue = number | string | boolean;

export interface ShaderParameter {
  id: string;
  name: string;
  label: string;
  type: 'float' | 'color' | 'boolean' | 'select' | 'texture';
  value: ShaderParameterValue;
  min?: number;
  max?: number;
  step?: number;
  options?: { label: string; value: number | string }[];
}

export interface StudioMaterialUniforms {
  uVideo: THREE.Texture;
  uGlyphs: THREE.Texture;
  uColorMap: THREE.Texture;
  uGradientOffset: number;
  uPrimaryColor: THREE.Color;
  uGridSize: THREE.Vector2;
  uNumGlyphs: number;
  uColorMode: number;
  uDitherType: number;
  uPixelSize: number;
  uDitherSpread: number;
  uColorDepth: number;
  uCharSpacing: number;
  uAsciiLuminance: number;
  uAsciiWeight: number;
  uScanlines: number;
  uResolution: THREE.Vector2;
  uAspect: number;
  uTime: number;
  uZoom: number;
  uPan: THREE.Vector2;
  uContrast: number;
  uBrightness: number;
  uSaturation: number;
  uShadows: number;
  uHighlights: number;
  uTemperature: number;
  uTint: number;
  uGrain: number;
  uVignette: number;
  uUseSourceAsBg: number;
  uSecondaryColor: THREE.Color;
}

export interface ShaderPreset {
  id: string;
  name: string;
  description: string;
  shaderCode: string;
  parameters?: ShaderParameter[];
}

import { GradientTemplate, ShaderPreset, AsciiPreset } from './types';

export const ASCII_PRESETS: AsciiPreset[] = [
  { id: 'classic', name: 'Classic', chars: ' .:-=+*#%@', asciiFontSize: 8, spacing: 1.0 },
  { id: 'blocky', name: 'Blocks', chars: ' ░▒▓█', asciiFontSize: 8, spacing: 1.2 },
  { id: 'binary', name: 'Binary', chars: '01', asciiFontSize: 8, spacing: 1.0 },
  { id: 'matrix', name: 'Matrix', chars: '日0123456789', asciiFontSize: 8, spacing: 1.1 },
  { id: 'minimal', name: 'Minimal', chars: ' ·◦●', asciiFontSize: 8, spacing: 1.0 },
  { id: 'bold', name: 'Impact', chars: ' @#W$', asciiFontSize: 8, spacing: 1.0 }
];

export const PSYCHEDELIC_TEMPLATES: GradientTemplate[] = [
  { id: 'lava', name: 'Lava Lamp', stops: [ { id: 'lava-0', color: '#000000', position: 0 }, { id: 'lava-1', color: '#ff0000', position: 0.4 }, { id: 'lava-2', color: '#ff8800', position: 0.7 }, { id: 'lava-3', color: '#ffff00', position: 1 } ] },
  { id: 'acid', name: 'Acid Trip', stops: [ { id: 'acid-0', color: '#440044', position: 0 }, { id: 'acid-1', color: '#00ff00', position: 0.3 }, { id: 'acid-2', color: '#ffff00', position: 0.6 }, { id: 'acid-3', color: '#00ffff', position: 1 } ] },
  { id: 'cyberpunk', name: 'Cyberpunk', stops: [ { id: 'cyber-0', color: '#000033', position: 0 }, { id: 'cyber-1', color: '#ff00ff', position: 0.45 }, { id: 'cyber-2', color: '#00ffff', position: 1 } ] },
  { id: 'forest-spirit', name: 'Forest Spirit', stops: [ { id: 'forest-0', color: '#001a00', position: 0 }, { id: 'forest-1', color: '#00ff66', position: 0.5 }, { id: 'forest-2', color: '#ffff00', position: 1 } ] },
