uniform sampler2D u_texture;
uniform float u_time;
uniform vec2 u_resolution;
uniform float u_jitterAmount;
uniform float u_smearIntensity;
uniform float u_noiseIntensity;
uniform float u_dropoutBlend;
uniform float u_creaseIntensity;
varying vec2 v_texCoord;

float hash11(float p) {
  p = fract(p * 1000.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash21(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 1000.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash21(i + vec2(0.0, 0.0)), hash21(i + vec2(1.0, 0.0)), u.x),
             mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), u.x), u.y);
}

vec3 rgb2yiq(vec3 c) {
  return vec3(
    0.299 * c.r + 0.587 * c.g + 0.114 * c.b,
    0.596 * c.r - 0.274 * c.g - 0.322 * c.b,
    0.211 * c.r - 0.523 * c.g + 0.312 * c.b
  );
}

vec3 yiq2rgb(vec3 c) {
  return vec3(
    1.0 * c.x + 0.956 * c.y + 0.621 * c.z,
    1.0 * c.x - 0.272 * c.y - 0.647 * c.z,
    1.0 * c.x - 1.106 * c.y + 1.703 * c.z
  );
}

void main() {
  float steppedTime = floor(u_time * 24.0) / 24.0;
  vec2 uv = v_texCoord;
  vec2 uvn = uv;

  // Spatial Distortions
  float jitter = (hash11(uv.y * 100.0 + steppedTime) - 0.5) * u_jitterAmount;
  uvn.x += jitter;

  // Tracking Crease
  float roll = fract(u_time * 0.15);
  float tcMask = smoothstep(0.04, 0.0, abs(uv.y - roll));
  uvn.x -= tcMask * (0.06 * u_creaseIntensity) * hash11(steppedTime);

  // Head switching
  float headSwitch = smoothstep(0.03, 0.0, uv.y);
  uvn.x += headSwitch * (hash11(steppedTime) * 0.03);

  // Color Sampling & Chroma Bleed
  vec3 col = vec3(0.0);
  float samples = 5.0;
  float spread = 0.005 * u_smearIntensity;
  vec3 centerSample = texture2D(u_texture, uvn).rgb;
  float Y = rgb2yiq(centerSample).x;
  vec2 IQ = vec2(0.0);
  for(float i = 0.0; i < 5.0; i++) {
    vec2 suv = uvn + vec2(i * spread, 0.0);
    vec3 srgb = texture2D(u_texture, suv).rgb;
    IQ += rgb2yiq(srgb).yz;
  }
  col = yiq2rgb(vec3(Y, IQ / samples));

  // Chromatic Aberration
  float abOffset = 0.002 * u_smearIntensity;
  col.r = texture2D(u_texture, uvn + vec2(-abOffset, 0.0)).r;
  col.b = texture2D(u_texture, uvn + vec2(abOffset, 0.0)).b;

  // Edge Ghosting & Interference
  vec2 ghostUV = uvn + vec2(-0.015, 0.0);
  vec3 ghost = texture2D(u_texture, ghostUV).rgb;
  col = mix(col, col + ghost * 0.2, 0.15 * u_smearIntensity);

  // AC Hum
  col *= 1.0 + sin(uv.y * 10.0 + u_time * 5.0) * 0.02;

  // Noise & Dropout Overlay
  float noiseValue = hash21(uv * vec2(0.2, 1.0) + steppedTime);
  col += (noiseValue - 0.5) * u_noiseIntensity;

  // Tape Dropouts
  float tapeY = floor(uv.y * 400.0);
  float rowNoise = hash21(vec2(tapeY, steppedTime));
  float trigger = step(0.995 - (0.01 * 0.05), rowNoise);
  float streakNoise = noise(vec2(uv.x * 50.0, tapeY + steppedTime * 10.0));
  float streak = step(0.5, streakNoise);
  float dropout = trigger * streak;

  vec2 dropDistort = vec2(streakNoise * 0.2 - 0.1, 0.0);
  vec3 sampled = texture2D(u_texture, uvn + dropDistort).rgb;
  float varSeed = fract(sin(tapeY * 12.9898) * 43758.5453);
  vec3 dropCol = mix(sampled.gbr * vec3(1.5, 0.8, 1.2),
                     sampled.brg * vec3(0.7, 1.7, 1.0),
                     step(0.5, varSeed));
  dropCol += (hash21(uv + steppedTime) - 0.5) * 0.3;
  col = mix(col, dropCol, dropout * u_dropoutBlend);

  // Scanlines
  float scanline = sin(uv.y * u_resolution.y * 1.0);
  col *= 1.0 - (scanline * 0.08);

  // Crease darkening
  col *= 1.0 - (tcMask * 0.4 * min(.5, u_creaseIntensity));

  // Color Grading
  col = col * 0.9 + 0.05;
  col.r *= 1.05;
  col.g *= 1.02;

  gl_FragColor = vec4(col, 1.0);
}`
