void main() {
    vec2 screen_uv = v_texCoord;
    vec2 offset = vec2(0.0);

    if (u_slice_direction == 2) {
        // Both (Grid) Mode
        vec2 cell_index = floor(screen_uv * u_bands);

        if (u_offset_mode == 1) {
            // Random mode: independent X and Y scatter
            offset.x = (random(cell_index + u_seed) * 2.0 - 1.0) * u_offset_max;
            offset.y = (random(cell_index + u_seed + vec2(12.3, 45.6)) * 2.0 - 1.0) * u_offset_max;
        } else {
            // Linear mode: radial explosion
            vec2 stable_cell_index = vec2(u_stable_x, u_stable_y) * (u_bands - 1.0);
            vec2 distance_vec = cell_index - stable_cell_index;
            offset.x = -(distance_vec.x / u_bands) * (1.0 - u_offset_max);
            offset.y = -(distance_vec.y / u_bands) * (1.0 - u_offset_max);
        }
    } else {
        // 1D Band Mode
        float band = 0.0;
        if (u_slice_direction == 0) {
            // Vertical slices
            band = floor(screen_uv.x * u_bands);
        } else {
            // Horizontal slices
            band = floor(screen_uv.y * u_bands);
