uniform sampler2D u_texture;
uniform sampler2D u_prevTexture;
uniform vec2 u_resolution;
uniform float u_time;

const vec3 backFill = vec3(1.0);
const float dotScale = 0.09;
const float sourceColors = 1.0;
const int shapeStyle = 1;
const float timeDrift = 0.2;

uniform float u_resolution_scale;
uniform float u_pattern_type;
uniform float u_temporal_smoothing;
uniform float u_edge_weight;
uniform float u_rendering_mode;

varying vec2 v_texCoord;

float mHash2(vec2 p) {
    vec3 p3  = fract(vec3(p.xyx) * 1000.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float mHash3(vec3 p3) {
	p3  = fract(p3 * 1000.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float mosaicNoise(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    return mix(mix(mix(mHash3(i + vec3(0,0,0)), mHash3(i + vec3(1,0,0)), f.x),
                   mix(mHash3(i + vec3(0,1,0)), mHash3(i + vec3(1,1,0)), f.x), f.y),
               mix(mix(mHash3(i + vec3(0,0,1)), mHash3(i + vec3(1,0,1)), f.x),
                   mix(mHash3(i + vec3(0,1,1)), mHash3(i + vec3(1,1,1)), f.x), f.y), f.z);
}

float calculateMosaicShape(vec2 uv, float r, float base_radius) {
  float d = length(uv - .5);
  float sizeRadius = (u_pattern_type == 1.0) ? .42 : .3;
  sizeRadius *= base_radius;
  d = 1. - smoothstep(0., sizeRadius, d);

  d = pow(d, 2. + base_radius);
  return d;
}

float sampleMosaicData(vec2 p, vec2 pad, vec2 offset, float contrast, float base_radius, float stepSize, out vec4 shapeColor) {
  p += offset;
  vec2 uv_i = floor(p);
  vec2 uv_f = fract(p);
  vec2 centerUV = (uv_i + .5 - offset) * pad + vec2(.5);

  vec4 tex = texture2D(u_texture, centerUV);

  shapeColor = tex;
  shapeColor.rgb *= shapeColor.a;

  return calculateMosaicShape(uv_f, 0.0, base_radius);
}

void main() {  
  const float step_multiplier = 6.;
  float aspect_ratio = u_resolution.x / u_resolution.y;
  float mapped_size = mix(.5, 1., u_resolution_scale);
  float cellsPerSide = mix(300., 7., pow(mapped_size, .7));
  cellsPerSide /= step_multiplier;
  float cellSizeY = 1. / cellsPerSide;
  vec2 pad = cellSizeY * vec2(1. / aspect_ratio, 1.);
  if (shapeStyle == 1 && u_pattern_type == 1.0) {
    pad *= .7;
  }

  float base_radius = 2. * pow(.5 * dotScale, .3);

  vec3 finalColor = vec3(0.);
  float finalAlpha = 0.;

  // Calculate cell alignment first to decide on mode
  vec2 gridSpacing = pad / step_multiplier;
  vec2 st = (v_texCoord - 0.5) / gridSpacing;
  vec2 i_st = floor(st + 0.5);

  if (u_pattern_type == 1.0) {
      if (mod(abs(i_st.x + i_st.y), 2.0) > 0.5) {
          vec2 f_st = fract(st + 0.5) - 0.5;
          if (abs(f_st.x) > abs(f_st.y)) i_st.x += (f_st.x > 0.0) ? 1.0 : -1.0;
          else i_st.y += (f_st.y > 0.0) ? 1.0 : -1.0;
      }
  }

  float randomVal = mosaicNoise(vec3(i_st, u_time * timeDrift));
  float exponent = exp2((u_edge_weight - 0.5) * 6.0);
  randomVal = pow(randomVal, exponent);

  // PATH A: Pixelated
  vec2 sampleUV = i_st * gridSpacing + 0.5;
  sampleUV = clamp(sampleUV, 0.0, 1.0);
  vec4 cellColor = texture2D(u_texture, sampleUV);
  vec3 colorHard = cellColor.rgb + backFill * (1. - cellColor.a);
  float opacityHard = 1.0;

  // PATH B: Soft
  vec2 uv = v_texCoord;
  uv -= vec2(.5);
  uv /= pad;
  float totalVolume = 0.;
  vec3 totalRGB = vec3(0.);
  float totalAlpha = 0.;
  vec4 shapeColor;
  float stepSize = 1. / step_multiplier;
  for (int i = 0; i < 6; i++) {
    for (int j = 0; j < 6; j++) {
      float x = -0.5 + float(i) * stepSize;
      float y = -0.5 + float(j) * stepSize;
      vec2 offset = vec2(x, y);
      if (u_pattern_type == 1.0) {
        float rowIndex = floor((y + .5) / stepSize);
        float colIndex = floor((x + .5) / stepSize);
        if (mod(rowIndex + colIndex, 2.) == 1.) continue;
      }
      float weight = sampleMosaicData(uv, pad, offset, 0.0, base_radius, stepSize, shapeColor);
      totalRGB    += shapeColor.rgb * weight;
      totalVolume += weight;
      totalAlpha  += weight;
    }
  }
  const float eps = 1e-4;
  totalRGB /= max(totalVolume, eps);
  totalAlpha /= max(totalVolume, eps);
  float mask = smoothstep(0.45, 0.55, totalVolume);
  vec3 colorSoft = totalRGB * mask + backFill * (1. - (totalAlpha * mask));
  float opacitySoft = 1.0;

  if (u_rendering_mode == 0.0) {
      finalColor = colorSoft;
      finalAlpha = opacitySoft;
  } else if (u_rendering_mode == 1.0) {
      finalColor = colorHard;
      finalAlpha = opacityHard;
  } else {
      finalColor = mix(colorSoft, colorHard, randomVal);
      finalAlpha = mix(opacitySoft, opacityHard, randomVal);
  }

  vec4 frameColor = vec4(finalColor, clamp(finalAlpha, 0.0, 1.0));
