  uniform float u_contrast;
  uniform float u_invert;
  uniform float u_smooth_time;
  uniform float u_grain_amount;
  uniform int u_roughness_fps;

  varying vec2 v_texCoord;

  float rand1(vec3 p) {
    vec4 p4 = fract(vec4(p.xyzx) * vec4(0.1031, 0.1030, 0.0973, 0.1099));
    p4 += dot(p4, p4.wzxy + 33.33);
    return fract((p4.x + p4.y + p4.z) * p4.w);
  }

  float blendEdge(float edge0, float edge1, float x) {
  return smoothstep(edge0, edge1, x);
  }

  float sigmoid(float x, float k) {
  return 1.0 / (1.0 + exp(-k * (x - 0.5)));
  }

  float fluidShape(vec2 local_uv, float brightness, float base_scale) {
  float dist = length(local_uv - .5);
  float max_r = .42;

  float actual_r = max((1.0 - brightness) * base_scale * max_r, 0.001);

  float field = 1. - blendEdge(0., actual_r, dist);
  return pow(field, 2. + base_scale);
  }

  float getLum(vec4 tex, float k, float invert) {
    vec3 c = vec3(
      sigmoid(tex.r, k),
      sigmoid(tex.g, k),
      sigmoid(tex.b, k)
    );
    float l = dot(vec3(0.2126, 0.7152, 0.0722), c);
    l = mix(1.0, l, tex.a);
    return (invert > 0.5) ? (1.0 - l) : l;
  }

  float evaluateCell(vec2 p, vec2 span, vec2 shift, float base_scale, float k, float invert, out vec4 pixel) {
  p += shift;
  vec2 id = floor(p);
  vec2 local = fract(p);
  vec2 lookup = (id + .5 - shift) * span + vec2(.5);

  vec4 raw = texture2D(u_texture, lookup);
  float b = getLum(raw, k, invert);

  pixel = raw;
  pixel.rgb *= pixel.a;

  return fluidShape(local, b, base_scale);
