    shaderCode: `precision highp float;
uniform sampler2D u_texture;
uniform vec2 u_resolution;
uniform float u_radius;
uniform float u_spacing;
varying vec2 v_texCoord;

void main() {
    int radius = int(u_radius);
    // Normalize kernel to a reference resolution so the visual kernel size
    // (in UV space) is identical regardless of export/preview resolution.
    // Matches the 1280-baseline used elsewhere (ASCII grid).
    vec2 src_size = vec2(1280.0, 720.0);
    vec2 uv = v_texCoord;
    float n = float((radius + 1) * (radius + 1));

    vec3 m0 = vec3(0.0), m1 = vec3(0.0), m2 = vec3(0.0), m3 = vec3(0.0);
    vec3 s0 = vec3(0.0), s1 = vec3(0.0), s2 = vec3(0.0), s3 = vec3(0.0);

    const int MAX_RADIUS = 10;

    // Quadrant 0: Bottom-Left
    for (int j = 0; j <= MAX_RADIUS; ++j) {
        if (j > radius) break;
        for (int i = 0; i <= MAX_RADIUS; ++i) {
            if (i > radius) break;
            vec3 c = texture2D(u_texture, clamp(uv + vec2(-float(i), -float(j)) * u_spacing / src_size, 0.0, 1.0)).rgb;
            m0 += c; s0 += c * c;
        }
    }

    // Quadrant 1: Bottom-Right
    for (int j = 0; j <= MAX_RADIUS; ++j) {
        if (j > radius) break;
        for (int i = 0; i <= MAX_RADIUS; ++i) {
            if (i > radius) break;
            vec3 c = texture2D(u_texture, clamp(uv + vec2(float(i), -float(j)) * u_spacing / src_size, 0.0, 1.0)).rgb;
            m1 += c; s1 += c * c;
        }
    }

    // Quadrant 2: Top-Right
    for (int j = 0; j <= MAX_RADIUS; ++j) {
        if (j > radius) break;
        for (int i = 0; i <= MAX_RADIUS; ++i) {
            if (i > radius) break;
            vec3 c = texture2D(u_texture, clamp(uv + vec2(float(i), float(j)) * u_spacing / src_size, 0.0, 1.0)).rgb;
            m2 += c; s2 += c * c;
        }
    }

    // Quadrant 3: Top-Left
    for (int j = 0; j <= MAX_RADIUS; ++j) {
        if (j > radius) break;
        for (int i = 0; i <= MAX_RADIUS; ++i) {
            if (i > radius) break;
            vec3 c = texture2D(u_texture, clamp(uv + vec2(-float(i), float(j)) * u_spacing / src_size, 0.0, 1.0)).rgb;
            m3 += c; s3 += c * c;
        }
    }

    float min_var = 10.0;
    vec3 final_color = vec3(0.0);
    vec3 mean, var;
    float variance;

    // Q0
    mean = m0 / n;
    var = abs(s0 / n - mean * mean);
    variance = var.r + var.g + var.b;
    if (variance < min_var) { min_var = variance; final_color = mean; }

    // Q1
    mean = m1 / n;
    var = abs(s1 / n - mean * mean);
    variance = var.r + var.g + var.b;
    if (variance < min_var) { min_var = variance; final_color = mean; }

    // Q2
    mean = m2 / n;
    var = abs(s2 / n - mean * mean);
    variance = var.r + var.g + var.b;
    if (variance < min_var) { min_var = variance; final_color = mean; }

    // Q3
    mean = m3 / n;
    var = abs(s3 / n - mean * mean);
    variance = var.r + var.g + var.b;
    if (variance < min_var) { min_var = variance; final_color = mean; }

    gl_FragColor = vec4(final_color, 1.0);
}
`
  }
];

import { useMemo, useEffect, useRef } from 'react';
import * as THREE from 'three';
import { buildGlyphCanvas } from '../utils';

export const useGlyphAtlas = (chars: string): THREE.Texture => {
  const prevTextureRef = useRef<THREE.CanvasTexture | null>(null);

  const texture = useMemo(() => {
    const canvas = buildGlyphCanvas(chars);

    // If canvas has zero dimensions (degenerate), return a 1x1 fallback
    if (canvas.width === 0 || canvas.height === 0) {
      const fallback = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
      fallback.needsUpdate = true;
      return fallback;
    }

    const tex = new THREE.CanvasTexture(canvas);
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;

    return tex;
  }, [chars]);

  // Dispose previous texture when chars change
  useEffect(() => {
    if (prevTextureRef.current && prevTextureRef.current !== texture) {
      prevTextureRef.current.dispose();
    }
    prevTextureRef.current = texture as THREE.CanvasTexture;

    return () => {
      texture.dispose();
    };
  }, [texture]);

  return texture;
};

