const DEFAULT_PASSTHROUGH_FRAGMENT = `
  precision highp float;
  uniform sampler2D u_texture;
  varying vec2 v_texCoord;
  void main() {
    gl_FragColor = texture2D(u_texture, v_texCoord);
  }
`;

/**
 * Native THREE ShaderMaterial subclass for presets, avoiding @react-three/drei
 */
class PresetShaderMaterial extends THREE.ShaderMaterial {
  constructor() {
    super({
      uniforms: {
        u_texture: { value: new THREE.Texture() },
        u_prevTexture: { value: new THREE.Texture() },
        u_time: { value: 0 },
        u_resolution: { value: new THREE.Vector2(1, 1) },
      },
      vertexShader: `
        varying vec2 v_texCoord;
        void main() {
          v_texCoord = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: DEFAULT_PASSTHROUGH_FRAGMENT
    });
  }
}

extend({ PresetShaderMaterial });

declare module '@react-three/fiber' {
  interface ThreeElements {
    presetShaderMaterial: any;
    colorizeMaterial: any;
    finishingMaterial: any;
  }
}

interface Props {
  media: FlowMediaItem;
  params: StudioParams;
  videoRef: React.MutableRefObject<HTMLVideoElement | null>;
  shaderParameters: ShaderParameter[];
  onShaderParametersChange: (params: ShaderParameter[]) => void;
  onCanvasReady: (canvas: HTMLCanvasElement) => void;
  onMediaLoad: (dims: { width: number, height: number }) => void;
  onVideoReady?: () => void;
  isSettingCenter?: boolean;
  onCenterSet?: (uv: THREE.Vector2) => void;
}

export const StudioRenderer: React.FC<Props> = ({
  media,
