      if (sortedStops[0].position > 0) gradient.addColorStop(0, sortedStops[0].color);
      sortedStops.forEach(s => gradient.addColorStop(s.position, s.color));
      if (sortedStops[sortedStops.length - 1].position < 1) gradient.addColorStop(1, sortedStops[sortedStops.length - 1].color);
    } else {
      gradient.addColorStop(0, '#000000');
      gradient.addColorStop(1, '#ffffff');
    }
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, 256, 1);
    texture.needsUpdate = true;
    return texture;
  }, [params.gradientStops]);

  const primaryColor = useMemo(() => new THREE.Color(params.primaryColor), [params.primaryColor]);
  const secondaryColor = useMemo(() => {
    return new THREE.Color(params.presetId === 'ascii' ? params.ascii.secondaryColor : params.dither.secondaryColor);
  }, [params.presetId, params.ascii.secondaryColor, params.dither.secondaryColor]);
  const panVec = useMemo(() => new THREE.Vector2(params.pan[0], params.pan[1]), [params.pan[0], params.pan[1]]);
  const resolutionVec = useMemo(() => {
    if (mediaIntrinsicSize) {
      return new THREE.Vector2(mediaIntrinsicSize.width, mediaIntrinsicSize.height);
    }
    return new THREE.Vector2(size.width, size.height);
  }, [mediaIntrinsicSize, size.width, size.height]);

  useEffect(() => {
    if (sourceTextureRef.current) { sourceTextureRef.current.dispose(); sourceTextureRef.current = null; }
    hasPrimedRef.current = false;

    if (media.type !== 'video') {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        const aspect = img.naturalWidth / img.naturalHeight;
        setMediaAspect(aspect);
        setMediaIntrinsicSize({ width: img.naturalWidth, height: img.naturalHeight });
        onMediaLoad({ width: img.naturalWidth, height: img.naturalHeight });
        const tex = new THREE.Texture(img);
        tex.minFilter = THREE.LinearFilter;
        tex.magFilter = THREE.LinearFilter;
        tex.needsUpdate = true;
        sourceTextureRef.current = tex;
        if (presetMaterialRef.current) {
          presetMaterialRef.current.uniforms.u_texture.value = tex;
        }
      };
      img.src = media.dataUrl;
      return;
    }

    const video = document.createElement('video');
    let blobUrl = '';
    const setupVideo = (url: string) => {
      if (!url.startsWith('blob:')) video.crossOrigin = 'anonymous';
      const source = document.createElement('source');
      source.src = url;
      if (media.mimeType) source.type = media.mimeType;
      video.appendChild(source);
      video.loop = true;
      video.muted = true;
      video.playsInline = true;
      video.autoplay = true;
      video.onloadedmetadata = () => {
        const aspect = video.videoWidth / video.videoHeight;
        setMediaAspect(aspect);
        setMediaIntrinsicSize({ width: video.videoWidth, height: video.videoHeight });
        onMediaLoad({ width: video.videoWidth, height: video.videoHeight });
      };
      video.onloadeddata = () => video.play().catch(() => {});
      video.load();
      videoRef.current = video;
      onVideoReady?.();
    };

    if (media.dataUrl.startsWith('data:')) {
      fetch(media.dataUrl)
        .then((res) => res.blob())
        .then((blob) => {
          blobUrl = URL.createObjectURL(blob);
          setupVideo(blobUrl);
        })
        .catch(console.error);
    } else {
      setupVideo(media.dataUrl);
    }

    const videoTex = new THREE.VideoTexture(video);
    videoTex.minFilter = THREE.LinearFilter;
    videoTex.magFilter = THREE.LinearFilter;
    videoTex.colorSpace = THREE.LinearSRGBColorSpace;
    sourceTextureRef.current = videoTex;
    if (presetMaterialRef.current) {
      presetMaterialRef.current.uniforms.u_texture.value = videoTex;
    }

    return () => {
      video.pause();
      video.innerHTML = '';
      video.removeAttribute('src');
      video.load();
      videoRef.current = null;
      videoTex.dispose();
      sourceTextureRef.current = null;
      if (blobUrl) URL.revokeObjectURL(blobUrl);
    };
  }, [media.dataUrl, media.type, onMediaLoad, onVideoReady]);

  useFrame((_state, delta) => {
    const cm = colorizeMaterialRef.current;
    const fm = finishingMaterialRef.current;
    const pm = presetMaterialRef.current;
    if (!cm || !fm || !pm) return;

    const sourceTex = sourceTextureRef.current;
    if (!sourceTex) return;

    if (pm.uniforms.u_texture.value !== sourceTex) {
      pm.uniforms.u_texture.value = sourceTex;
    }

    const clockTime = elapsedTimeRef.current += delta;
    const activeFps = params.presetId === 'ascii' ? params.ascii.fps : 
                      params.presetId === 'dither' ? params.dither.fps : 60;
    const targetFps = activeFps || 60;
    const frameInterval = 1.0 / targetFps;
    const isImage = media.type === 'image';
    const videoTime = isImage ? 0 : (videoRef.current ? videoRef.current.currentTime : clockTime);

    const shouldRender = targetFps >= 60 || lastRenderTimeRef.current < 0 || (videoTime - lastRenderTimeRef.current) >= frameInterval;

    if (pm.uniforms.u_temporal_smoothing) {
      invalidate(); // keep frameloop alive for history
    }

    // Animate map logic: follows playhead for video, real-time for image
    const animTime = isImage ? clockTime : videoTime;

    let currentOffset = params.gradientOffset;
    if (params.gradientAnimated) {
      currentOffset = (params.gradientOffset + animTime * 0.3 * params.gradientSpeed) % 1.0;
      invalidate();
    }
    if (cm.uniforms.uGradientOffset) {
      cm.uniforms.uGradientOffset.value = currentOffset;
    }

    if (shouldRender) {
      lastRenderTimeRef.current = videoTime;
      const readFbo = effectFbos[pingPongRef.current.readIndex];
      const writeFbo = effectFbos[pingPongRef.current.writeIndex];

      if (!hasPrimedRef.current && shouldRender && pm.fragmentShader !== DEFAULT_PASSTHROUGH_FRAGMENT) {
        const blackTex = primeBlackTextureRef.current;
        const savedTemporal = pm.uniforms.u_temporal_smoothing?.value;
        const savedSmooth = pm.uniforms.u_smooth_time?.value;
        if (pm.uniforms.u_temporal_smoothing) pm.uniforms.u_temporal_smoothing.value = 0;
        if (pm.uniforms.u_smooth_time) pm.uniforms.u_smooth_time.value = 0;
        pm.uniforms.u_prevTexture.value = blackTex;
        gl.setRenderTarget(readFbo);
        gl.render(effectScene, fboCamera);
        gl.setRenderTarget(null);
        if (pm.uniforms.u_temporal_smoothing) pm.uniforms.u_temporal_smoothing.value = savedTemporal;
        if (pm.uniforms.u_smooth_time) pm.uniforms.u_smooth_time.value = savedSmooth;
        hasPrimedRef.current = true;
      }

      pm.uniforms.u_time.value = videoTime;
      if (pm.uniforms.u_prevTexture) pm.uniforms.u_prevTexture.value = readFbo.texture;
      if (pm.uniforms.u_resolution) pm.uniforms.u_resolution.value.set(writeFbo.width, writeFbo.height);

      gl.setRenderTarget(writeFbo);
      gl.render(effectScene, fboCamera);
      gl.setRenderTarget(null);

      cm.uVideo = writeFbo.texture;
      gl.setRenderTarget(fboB);
      gl.render(colorizeScene, fboCamera);
      gl.setRenderTarget(null);

      const temp = pingPongRef.current.readIndex;
      pingPongRef.current.readIndex = pingPongRef.current.writeIndex;
      pingPongRef.current.writeIndex = temp;

      fm.tDiffuse = fboB.texture;
      fm.uTime = clockTime;
    }

    if (!isImage) invalidate();
  });

  useEffect(() => { invalidate(); }, [invalidate, params, shaderParameters, mediaAspect, mediaIntrinsicSize, media.dataUrl, media.type, size.width, size.height]);

  return (
    <>
      {createPortal(
        <mesh>
          <planeGeometry args={[1, 1]} />
          <presetShaderMaterial ref={presetMaterialRef} />
        </mesh>,
        effectScene
      )}

      {createPortal(
        <mesh>
          <planeGeometry args={[1, 1]} />
          <colorizeMaterial
            ref={colorizeMaterialRef}
            uVideo={effectFbos[0].texture}
            uGlyphs={glyphAtlas}
            uColorMap={colorMapTexture}
            uGradientOffset={params.gradientOffset}
            uNumGlyphs={params.ascii.chars.length}
            uGridSize={computedGridSize}
            uCharSpacing={params.ascii.charSpacing}
            uAsciiLuminance={params.ascii.asciiLuminance}
            uAsciiWeight={params.ascii.asciiWeight}
            uEffectType={params.presetId === 'ascii' ? 0 : params.presetId === 'dither' ? 1 : -1}
            uDitherType={params.dither.ditherType}
            uPixelSize={params.dither.pixelSize}
            uDitherSpread={params.dither.ditherSpread}
            uColorMode={params.colorMode}
            uColorDepth={params.dither.colorDepth}
            uPrimaryColor={primaryColor}
            uAspect={mediaAspectForShader}
            uContrast={params.contrast}
            uBrightness={params.brightness}
            uSaturation={params.saturation}
            uShadows={params.shadows}
            uHighlights={params.highlights}
            uTemperature={params.temperature}
            uTint={params.tint}
            uResolution={resolutionVec}
            uUseSourceAsBg={params.presetId === 'ascii' ? (params.ascii.useSourceAsBg ? 1.0 : 0.0) : (params.dither.useSourceAsBg ? 1.0 : 0.0)}
            uSecondaryColor={secondaryColor}
          />
        </mesh>,
        colorizeScene
      )}

      <group>
        <mesh 
          scale={[meshDimensions.width, meshDimensions.height, 1]}
          onPointerDown={(e) => {
            if (isSettingCenter) {
              e.stopPropagation();
              onCenterSet?.(e.uv!);
            }
          }}
        >
          <planeGeometry args={[1, 1]} />
          <finishingMaterial
            ref={finishingMaterialRef}
            tDiffuse={fboB.texture}
            uTime={0}
            uZoom={params.zoom}
            uPan={panVec}
            uGrain={params.grain}
            uVignette={params.vignette}
            uFlicker={params.flicker}
            transparent={true}
          />
        </mesh>
      </group>
      {params.bloomIntensity > 0 && (
        <EffectComposer>
          <Bloom 
            mipmapBlur 
            intensity={params.bloomIntensity} 
            luminanceThreshold={params.bloomThreshold} 
            luminanceSmoothing={params.bloomSmoothing}
            radius={params.bloomRadius}
          />
        </EffectComposer>
      )}
    </>
  );
};

