import React, { useEffect, useRef } from 'react';
import { SharedPreviewRenderer } from '../services/previewRenderer';
import { FlowMediaItem, GradientStop } from '../types';
import { PRESET_SHADERS } from '../constants';

interface Props {
  effect: { id: string; name: string; icon: any };
  media: FlowMediaItem | null;
  videoElement: HTMLVideoElement | null;
  isActive: boolean;
  disabled?: boolean;
  tooltip?: string;
  onClick: () => void;
  isPlaying?: boolean;

  // Current Global State (to show combined previews)
  activePresetId?: string | null;
  pixelSize?: number;
  colorDepth?: number;
  colorMode?: number;
  gradientStops?: GradientStop[];
  gradientOffset?: number;
  contrast?: number;
  brightness?: number;
  saturation?: number;
  shadows?: number;
  highlights?: number;
  temperature?: number;
  tint?: number;
  grain?: number;
  vignette?: number;
}

const SHADER_MAP: Record<string, string> = {
  none: `precision highp float; uniform sampler2D u_texture; varying vec2 v_texCoord; void main() { gl_FragColor = texture2D(u_texture, v_texCoord); }`,
  ascii: `precision highp float; uniform sampler2D u_texture; varying vec2 v_texCoord; void main() { gl_FragColor = texture2D(u_texture, v_texCoord); }`,
  dither: `precision highp float; uniform sampler2D u_texture; varying vec2 v_texCoord; void main() { gl_FragColor = texture2D(u_texture, v_texCoord); }`,
  'preset-color-lut': `precision highp float;
    uniform sampler2D u_texture;
    varying vec2 v_texCoord;
    void main() {
      vec3 c = texture2D(u_texture, v_texCoord).rgb;
      c.r *= 1.08;
      c.g *= 1.02;
      c.b *= 0.88;
      c = (c - 0.5) * 1.1 + 0.5;
      float luma = dot(c, vec3(0.299, 0.587, 0.114));
      c = mix(vec3(luma), c, 1.15);
      gl_FragColor = vec4(clamp(c, 0.0, 1.0), 1.0);
    }`,
  'preset-film-grain': `precision highp float;
    uniform sampler2D u_texture;
    uniform float u_time;
    varying vec2 v_texCoord;
    float rand(vec2 co, float seed) {
      return fract(sin(dot(co + seed, vec2(12.9898, 78.233))) * 43758.5453);
    }
    void main() {
      vec2 uv = v_texCoord;
      vec3 c = texture2D(u_texture, uv).rgb;
      float n = (rand(uv * 500.0, u_time) - 0.5) * 0.3;
      c += n;
      vec2 ctr = uv - 0.5;
      float vig = 1.0 - smoothstep(0.3, 0.9, length(ctr)) * 0.4;
      c *= vig;
      gl_FragColor = vec4(clamp(c, 0.0, 1.0), 1.0);
    }`
};

function getShaderForEffect(effectId: string): string {
  let shader = SHADER_MAP[effectId];
  if (!shader) {
    const preset = PRESET_SHADERS.find(p => p.id === effectId);
    if (preset) {
      shader = preset.shaderCode;
      for (const p of (preset.parameters || [])) {
        if (p.type === 'float') {
          shader = shader.replace(
            new RegExp('uniform float ' + p.name + ';', 'g'),
            'float ' + p.name + ' = ' + Number(p.value).toFixed(4) + ';'
          );
        } else if (p.type === 'select') {
          shader = shader.replace(
            new RegExp('uniform int ' + p.name + ';', 'g'),
            'const int ' + p.name + ' = ' + Math.round(Number(p.value)) + ';'
          );
        } else if (p.type === 'boolean') {
          shader = shader.replace(
            new RegExp('uniform float ' + p.name + ';', 'g'),
            'float ' + p.name + ' = ' + (p.value ? '1.0' : '0.0') + ';'
          );
        } else if (p.type === 'texture') {
          // Remove sampler2D uniform — preview can't bind extra textures
          shader = shader.replace(
            new RegExp('uniform sampler2D ' + p.name + ';\\s*', 'g'), ''
          );
          // Replace any usage with u_texture as fallback
          shader = shader.replace(new RegExp(p.name, 'g'), 'u_texture');
        } else if (p.type === 'color') {
          // Inline color as vec3 constant
          const hex = String(p.value || '#ffffff');
          const r = parseInt(hex.slice(1, 3), 16) / 255;
          const g = parseInt(hex.slice(3, 5), 16) / 255;
          const b = parseInt(hex.slice(5, 7), 16) / 255;
          shader = shader.replace(
            new RegExp('uniform vec3 ' + p.name + ';', 'g'),
            'vec3 ' + p.name + ' = vec3(' + r.toFixed(4) + ', ' + g.toFixed(4) + ', ' + b.toFixed(4) + ');'
          );
        }
      }
      shader = shader.replace(new RegExp('uniform sampler2D u_prevTexture;\\s*', 'g'), '');
      shader = shader.replace(/u_prevTexture/g, 'u_texture');
    } else {
      shader = SHADER_MAP.none;
    }
  }
  return shader;
}

export const FilterPreviewCard: React.FC<Props> = React.memo(({ 
  effect, media, videoElement, isActive, disabled, tooltip, onClick, isPlaying,
  activePresetId, pixelSize, colorDepth, colorMode, 
  gradientStops, gradientOffset, contrast, brightness,
  saturation, shadows, highlights, temperature, tint, grain, vignette
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // Downscaled bitmap source (256px max edge) so per-tick texImage2D uploads
  // don't unpack the full-resolution image on every slider change.
  const imageRef = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const renderFrame = () => {
      if (!canvasRef.current) return;
      const source = media?.type === 'video' ? videoElement : imageRef.current;
      if (!source) return;
      try {
        const shared = SharedPreviewRenderer.getInstance();

        if (colorMode === 2 && gradientStops && gradientStops.length >= 2) {
          shared.updateGradient(gradientStops, gradientOffset ?? 0);
        }

        const time = (media?.type === 'video' && videoElement) ? videoElement.currentTime : 0;

        // Determine shader and stylization for this effect's preview
        const isStylization = effect.id === 'ascii' || effect.id === 'dither';
        const currentShaderId = isStylization ? 'none' : effect.id;
        const fragmentSource = getShaderForEffect(currentShaderId);

        const effectType = effect.id === 'ascii' ? 0 : effect.id === 'dither' ? 1 : -1;

        // Override pixelSize and colorDepth for ASCII/Dither previews
        // so the effect is clearly visible at 80×80 thumbnail scale
        const previewPixelSize = (effect.id === 'ascii' || effect.id === 'dither') ? 2 : (pixelSize ?? 8);
        const previewColorDepth = (effect.id === 'dither') ? 3 : (colorDepth ?? 8);

        // Colorize and Finishing settings are still passed through to remain applied globally.
        shared.renderToCanvas(
          canvasRef.current,
          fragmentSource,
          source,
          time,
          colorMode ?? 1,
          effectType,
          previewPixelSize,
          previewColorDepth,
          contrast ?? 1.0,
          brightness ?? 0.0,
          saturation ?? 1.0,
          shadows ?? 0.0,
          highlights ?? 0.0,
          temperature ?? 0.0,
          tint ?? 0.0,
          grain ?? 0.0,
          vignette ?? 0.0
        );
      } catch (e) {
        console.warn('Preview render failed:', e);
      }
    };

    renderFrame();

    if (media?.type === 'video' && isPlaying) {
      let rafId: number;
      let lastRender = 0;
      const loop = (timestamp: number) => {
        if (timestamp - lastRender >= 100) {
          lastRender = timestamp;
          renderFrame();
        }
        rafId = requestAnimationFrame(loop);
      };
      rafId = requestAnimationFrame(loop);
      return () => cancelAnimationFrame(rafId);
    }

    const timer = setTimeout(renderFrame, 150);
    return () => clearTimeout(timer);
  }, [
    effect.id, media, videoElement, isPlaying, 
    pixelSize, colorDepth, colorMode, gradientStops, gradientOffset, contrast, 
    brightness, saturation, shadows, highlights, temperature, tint, grain, vignette
  ]);

  useEffect(() => {
    if (media?.type === 'image') {
      let cancelled = false;
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        if (cancelled) return;
        // Downscale once to a small offscreen canvas so subsequent
        // per-slider-tick texImage2D uploads stay cheap regardless of
        // the source image's native resolution.
        const MAX_EDGE = 256;
        const srcW = img.naturalWidth || 1;
        const srcH = img.naturalHeight || 1;
        const scale = Math.min(1, MAX_EDGE / Math.max(srcW, srcH));
        const dstW = Math.max(1, Math.round(srcW * scale));
        const dstH = Math.max(1, Math.round(srcH * scale));
        const off = document.createElement('canvas');
        off.width = dstW;
        off.height = dstH;
        const ctx = off.getContext('2d');
        if (!ctx) return;
        ctx.drawImage(img, 0, 0, dstW, dstH);
        imageRef.current = off;
      };
      img.src = media.dataUrl;
      return () => { cancelled = true; };
    } else {
      imageRef.current = null;
    }
  }, [media?.id, media?.dataUrl, media?.type]);

  return (
    <button
      onClick={onClick}
      disabled={disabled}
      title={tooltip}
      className={`flex flex-col gap-2 p-1.5 rounded-xl border transition-all text-left overflow-hidden group ${
        disabled
          ? 'border-[#595959] bg-[#0e0e0e] opacity-40 cursor-not-allowed'
          : isActive
            ? 'border-[#969696] bg-white/5'
            : 'border-[#595959] bg-[#0e0e0e] hover:border-[#7a7a7a]'
      }`}
    >
      <div className="w-full aspect-square rounded-lg bg-black overflow-hidden ring-1 ring-white/5 relative">
        <canvas 
          ref={canvasRef} 
          width={80} 
          height={80} 
          className="w-full h-full object-cover transition-opacity duration-300" 
        />
        {!media && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#1a1a1a]">
            <effect.icon size={16} className="text-neutral-600" />
          </div>
        )}
      </div>
      <div className="px-1 pb-0.5 truncate">
        <span className={`text-[11px] font-medium tracking-[0.1px] transition-colors ${
          isActive ? 'text-white' : 'text-[rgba(218,220,224,0.75)]'
        }`}>
          {effect.name}
        </span>
      </div>
    </button>
  );
});

