export const GradientMapSwatch: React.FC<{
  template: GradientTemplate;
  isActive: boolean;
  isCustom?: boolean;
  onClick: () => void;
  onDelete?: () => void;
}> = React.memo(({ template, isActive, isCustom, onClick, onDelete }) => {
  const gradientCss = useMemo(() => {
    const sorted = [...template.stops].sort((a, b) => a.position - b.position);
    if (sorted.length === 0) return '#000';
    const cssStops: string[] = [];
    if (sorted[0].position > 0) cssStops.push(`${sorted[0].color} 0%`);
    cssStops.push(...sorted.map(s => `${s.color} ${s.position * 100}%`));
    if (sorted[sorted.length - 1].position < 1) cssStops.push(`${sorted[sorted.length - 1].color} 100%`);
    return `linear-gradient(to bottom, ${cssStops.join(', ')})`;
  }, [template.stops]);

  return (
    <button onClick={onClick} className={`relative h-8 rounded-lg border-2 transition-all overflow-hidden group ${isActive ? 'border-white' : 'border-white/5 hover:border-white/20'}`} title={template.name}>
      <div className="w-full h-full" style={{ background: gradientCss }} />
      {isCustom && onDelete && (
        <div className="absolute top-0 right-0 w-3.5 h-3.5 bg-black/70 rounded-bl-md flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity" onClick={(e) => { e.stopPropagation(); onDelete(); }}>
          <Trash2 size={8} className="text-red-400" />
        </div>
      )}
    </button>
  );
});

