  isSettingCenter: boolean;
  videoRef: React.RefObject<HTMLVideoElement | null>;

  onUpdatePresetParam: <P extends 'ascii' | 'dither', K extends keyof StudioParams[P]>(preset: P, key: K, value: StudioParams[P][K]) => void;
  onSelectEffect: (effect: UnifiedEffect) => void;
  onToggleShaderFilters: (enabled: boolean) => void;
  onApplyAsciiPreset: (name: string) => void;
  onUpdateShaderParam: (index: number, value: ShaderParameterValue) => void;
  onSetIsSettingCenter: (v: boolean) => void;
}

export const LeftSidebar: React.FC<LeftSidebarProps> = ({
  params, media, shaderParameters, allEffects,
  isPlaying, isSettingCenter, videoRef,
  onUpdatePresetParam, onSelectEffect, onToggleShaderFilters,
  onApplyAsciiPreset, onUpdateShaderParam, onSetIsSettingCenter,
}) => {
  const isFiltersEnabled = params.presetId !== null;
  const isImage = media?.type === 'image';

  // Stable per-effect click handlers so React.memo on FilterPreviewCard
  // can skip renders when only Finishing slider values change.
  const effectClickHandlers = React.useMemo(() => {
    const map = new Map<string, () => void>();
    for (const effect of allEffects) {
      map.set(effect.id, () => onSelectEffect(effect));
    }
    return map;
  }, [allEffects, onSelectEffect]);

  return (
    <div className="w-[300px] h-full flex flex-col overflow-clip px-[10px] py-[12px]">
      <div className={`flex flex-col gap-[20px] items-start w-full flex-1 min-h-0 transition-opacity duration-300 ${!media ? 'opacity-40 pointer-events-none' : 'opacity-100'}`}>
        <div className="flex-1 w-full flex flex-col gap-[24px] overflow-y-auto dark-scrollbar pr-1 pb-4 pt-2">
          {/* Shader Filters */}
          <div className="flex flex-col gap-[8px] w-full">
            <SectionLabel action={<HeaderToggle checked={isFiltersEnabled} onChange={onToggleShaderFilters} />}>
              Filters
            </SectionLabel>
            <div className="grid grid-cols-2 gap-1.5 w-full">
              {allEffects.map(effect => {
                const cardDisabled = !!effect.videoOnly && isImage;
                return (
                  <FilterPreviewCard
                    key={effect.id}
                    effect={effect}
                    media={media}
                    videoElement={videoRef.current}
                    isActive={params.presetId === effect.id}
                    onClick={effectClickHandlers.get(effect.id)!}
                    isPlaying={isPlaying}
                    activePresetId={params.presetId}
                    pixelSize={params.dither.pixelSize}
                    colorDepth={params.dither.colorDepth}
                    colorMode={params.colorMode}
                    gradientStops={params.gradientStops}
                    gradientOffset={params.gradientOffset}
                    contrast={params.contrast}
                    brightness={params.brightness}
                    saturation={params.saturation}
                    shadows={params.shadows}
                    highlights={params.highlights}
                    temperature={params.temperature}
                    tint={params.tint}
                    grain={params.grain}
                    vignette={params.vignette}
                    disabled={cardDisabled}
                    tooltip={cardDisabled ? "This effect doesn't apply to images" : undefined}
                  />
                );
              })}
            </div>
          </div>

          {/* Shader Tuning */}
          {isFiltersEnabled && (
            <div className="flex flex-col gap-[8px] w-full animate-in fade-in duration-300">
              <SectionLabel>{params.presetId === 'ascii' ? 'ASCII Logic' : params.presetId === 'dither' ? 'Dither Logic' : 'Shader Tuning'}</SectionLabel>
              <div className="flex flex-col gap-1.5 w-full">
                {params.presetId && params.presetId !== 'ascii' && params.presetId !== 'dither' && shaderParameters.map((param, idx) => {
                  if (params.presetId === 'preset-banded-offset') {
                    const offsetMode = shaderParameters.find(p => p.name === 'u_offset_mode')?.value;
                    const isLinear = offsetMode === 0;
                    const isRandom = offsetMode === 1;

                    if (!isLinear && (param.name === 'u_stable_x' || param.name === 'u_stable_y')) return null;
                    if (!isRandom && param.name === 'u_seed') return null;
                  }

                  if (params.presetId === 'preset-mosaic-grid') {
                    const edgeMode = shaderParameters.find(p => p.name === 'u_rendering_mode')?.value;
                    const isMix = edgeMode === 2;
                    if (!isMix && param.name === 'u_edge_weight') return null;
                  }

                  return (
                  <React.Fragment key={param.id}>
                    {param.type === 'float' && (
                      <RangeSlider label={param.label} value={param.value as number} min={param.min ?? 0} max={param.max ?? 1} step={param.step ?? 0.01} onChange={(v) => onUpdateShaderParam(idx, v)} />
                    )}
                    {(param.type === 'select' || param.type === 'texture') && param.options && (
                      <FieldDropdown label={param.label} value={param.options.find(o => o.value === param.value)?.label || ''} options={param.options.map(o => o.label)} onChange={(label) => {
                        const opt = param.options!.find(o => o.label === label);
                        if (opt) onUpdateShaderParam(idx, opt.value);
                      }} />
                    )}
                    {param.type === 'boolean' && (
                      <div className="px-1 py-1">
                        <Toggle label={param.label} checked={!!param.value} onChange={(v) => onUpdateShaderParam(idx, v)} />
                      </div>
                    )}
                    {param.type === 'color' && (
                      <ColorInput label={param.label} value={String(param.value)} onChange={(v) => onUpdateShaderParam(idx, v)} />
                    )}
                    {((param.name === 'u_center_y' && params.presetId === 'preset-zoom') ||
                      (param.name === 'u_stable_y' && params.presetId === 'preset-banded-offset')) && (
                      <div className="mt-1">
                        <PillButton variant={isSettingCenter ? 'solid' : 'outline'} icon={<Crosshair size={16} />} onClick={() => onSetIsSettingCenter(!isSettingCenter)} className="w-full">
                          {isSettingCenter ? 'Cancel Selection' : 'Set Center on Canvas'}
                        </PillButton>
                      </div>
                    )}
                  </React.Fragment>
                )})}
                {params.presetId === 'ascii' && (
                  <>
                    <FieldDropdown label="Preset" value={ASCII_PRESETS.find(p => p.id === params.asciiPresetId)?.name || 'Custom'} options={ASCII_PRESETS.map(p => p.name)} onChange={onApplyAsciiPreset} />
                    <TextInput label="Glyphs" value={params.ascii.chars} onChange={(v) => onUpdatePresetParam('ascii', 'chars', v || ' ')} placeholder="ASCII string..." />
                    <RangeSlider label="Size" value={params.ascii.asciiFontSize} min={4} max={40} step={1} onChange={(v) => onUpdatePresetParam('ascii', 'asciiFontSize', v)} />
                    <RangeSlider label="Exposure" value={params.ascii.asciiLuminance} min={0.2} max={3.0} step={0.05} onChange={(v) => onUpdatePresetParam('ascii', 'asciiLuminance', v)} />
                    <RangeSlider label="Char Spacing" value={params.ascii.charSpacing} min={0.5} max={2.0} step={0.05} onChange={(v) => onUpdatePresetParam('ascii', 'charSpacing', v)} />
                    <RangeSlider label="Framerate" value={params.ascii.fps} min={1} max={60} step={1} formatValue={(v) => `${v} FPS`} onChange={(v) => onUpdatePresetParam('ascii', 'fps', v)} />
                    <Toggle label="Transparent Bg (Use Source)" checked={params.ascii.useSourceAsBg} onChange={(v) => onUpdatePresetParam('ascii', 'useSourceAsBg', v)} />
                    <div className={`transition-opacity duration-200 ${params.ascii.useSourceAsBg ? 'opacity-30 pointer-events-none' : 'opacity-100'}`}>
                      <ColorInput label="Background Color" value={params.ascii.secondaryColor} onChange={(v) => onUpdatePresetParam('ascii', 'secondaryColor', v)} />
                    </div>
                  </>
                )}
                {params.presetId === 'dither' && (
                  <>
                    <FieldDropdown label="Dither Pattern" value={DITHER_TYPE_ITEMS.find(d => d.value === String(params.dither.ditherType))?.label || 'Bayer 4×4'} options={DITHER_TYPE_ITEMS.map(d => d.label)} onChange={(label) => {
                      const item = DITHER_TYPE_ITEMS.find(d => d.label === label);
                      if (item) onUpdatePresetParam('dither', 'ditherType', Number(item.value) as any);
                    }} />
                    <RangeSlider label="Pixel Size" value={params.dither.pixelSize} min={1} max={32} step={1} formatValue={(v) => `${v}px`} onChange={(v) => onUpdatePresetParam('dither', 'pixelSize', v)} />
                    <RangeSlider label="Spread" value={params.dither.ditherSpread} min={0} max={3} step={0.1} onChange={(v) => onUpdatePresetParam('dither', 'ditherSpread', v)} />
                    <RangeSlider label="Depth" value={params.dither.colorDepth} min={2} max={16} step={1} onChange={(v) => onUpdatePresetParam('dither', 'colorDepth', v)} />
                    <RangeSlider label="Framerate" value={params.dither.fps} min={1} max={60} step={1} formatValue={(v) => `${v} FPS`} onChange={(v) => onUpdatePresetParam('dither', 'fps', v)} />
                    <Toggle label="Transparent Bg (Use Source)" checked={params.dither.useSourceAsBg} onChange={(v) => onUpdatePresetParam('dither', 'useSourceAsBg', v)} />
                    <div className={`transition-opacity duration-200 ${params.dither.useSourceAsBg ? 'opacity-30 pointer-events-none' : 'opacity-100'}`}>
                      <ColorInput label="Background Color" value={params.dither.secondaryColor} onChange={(v) => onUpdatePresetParam('dither', 'secondaryColor', v)} />
                    </div>
                  </>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

