export const GradientTrack: React.FC<{
  stops: GradientStop[];
  onChange: (id: string, position: number, color?: string) => void;
  onDelete?: (id: string) => void;
  onAdd?: (position: number) => void;
}> = ({ stops, onChange, onDelete, onAdd }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const wasJustDragging = useRef(false);

  const getGradientCss = (stops: GradientStop[]) => {
    const sorted = [...stops].sort((a, b) => a.position - b.position);
    if (sorted.length === 0) return "#000";
    const cssStops: string[] = [];
    if (sorted[0].position > 0) cssStops.push(`${sorted[0].color} 0%`);
    cssStops.push(...sorted.map((s) => `${s.color} ${s.position * 100}%`));
    if (sorted[sorted.length - 1].position < 1)
      cssStops.push(`${sorted[sorted.length - 1].color} 100%`);
    return `linear-gradient(to bottom, ${cssStops.join(", ")})`;
  };

  const handleStopPointerDown = (e: React.PointerEvent, stopId: string) => {
    e.stopPropagation();
    (e.target as Element).setPointerCapture?.(e.pointerId);
    setDraggingId(stopId);
  };

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (draggingId === null || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const pos = (e.clientY - rect.top) / rect.height;
      onChange(draggingId, Math.max(0, Math.min(1, pos)));
    },
    [draggingId, onChange],
  );

  const handlePointerUp = useCallback(() => {
    if (draggingId !== null) {
      wasJustDragging.current = true;
      requestAnimationFrame(() => {
        wasJustDragging.current = false;
      });
    }
    setDraggingId(null);
  }, [draggingId]);

  const handleTrackPointerDown = (e: React.PointerEvent) => {
    if (wasJustDragging.current || !containerRef.current || !onAdd) return;
    const rect = containerRef.current.getBoundingClientRect();
    const pos = (e.clientY - rect.top) / rect.height;
    onAdd(Math.max(0, Math.min(1, pos)));
  };

  // Sort for display in numeric list
  const sortedStops = [...stops].sort((a, b) => a.position - b.position);

  return (
    <div className="flex gap-8 items-stretch h-52 select-none pr-1">
      {/* Visual Track Area */}
      <div className="relative w-10">
        <div
          className="absolute top-1 bottom-1 right-0 w-3.5 rounded-sm border border-white/10 overflow-visible cursor-crosshair"
          style={{ touchAction: "none" }}
          onPointerDown={handleTrackPointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerCancel={handlePointerUp}
          ref={containerRef}
        >
          {/* Inner clip layer — gradient background is clipped to rounded rect */}
          <div className="absolute inset-0 rounded-sm overflow-hidden pointer-events-none">
            <div
              className="w-full h-full"
              style={{ background: getGradientCss(stops) }}
            />
          </div>
          {stops.map((stop) => (
            <div
              key={stop.id}
              onPointerDown={(e) => handleStopPointerDown(e, stop.id)}
              className={`absolute right-full mr-1.5 w-6 h-6 flex items-center justify-center cursor-ns-resize group/handle z-20 transition-transform ${draggingId === stop.id ? "scale-110" : ""}`}
              style={{
                top: `${stop.position * 100}%`,
                transform: "translateY(-50%)",
                touchAction: "none",
              }}
            >
              {/* Pointer (Beak) pointing RIGHT into the track — pointer-events-none so it can't intercept track clicks */}
              <div
                className={`absolute -right-1.5 w-0 h-0 border-t-[4px] border-t-transparent border-b-[4px] border-b-transparent border-l-[6px] transition-colors pointer-events-none ${draggingId === stop.id ? "border-l-blue-500" : "border-l-white/60 group-hover/handle:border-l-white"}`}
              />

              {/* The Figma Handle Square */}
              <div
                className={`w-4 h-4 rounded-[3px] border-2 shadow-2xl transition-all ${
                  draggingId === stop.id
                    ? "border-blue-500 ring-2 ring-blue-500/20"
                    : "border-white/40 group-hover/handle:border-white shadow-black/50"
                }`}
                style={{ backgroundColor: stop.color }}
              />
            </div>
          ))}
          {/* Subtle grid lines background */}
          <div
            className="absolute inset-0 pointer-events-none opacity-5"
            style={{
              background:
                "linear-gradient(rgba(255,255,255,1) 1px, transparent 1px)",
              backgroundSize: "100% 20%",
            }}
          />
        </div>
      </div>

      {/* Numeric List Area */}
      <div className="flex-1 flex flex-col gap-2 overflow-y-auto dark-scrollbar pr-1">
        {sortedStops.map((stop) => (
          <GradientStopRow
            key={stop.id}
            stop={stop}
            isDragging={draggingId === stop.id}
            canDelete={stops.length > 2}
            onChange={onChange}
            onDelete={onDelete}
          />
        ))}
        <button
          onClick={() => onAdd && onAdd(0.5)}
          className="flex items-center justify-center h-7 w-full border border-dashed border-white/10 rounded-lg text-neutral-500 hover:text-white hover:border-white/20 transition-all mt-1"
        >
          <Plus size={14} />
        </button>
      </div>
    </div>
  );
};

/** Individual stop row — isolated state for editable position input */
const GradientStopRow: React.FC<{
  stop: GradientStop;
  isDragging: boolean;
  canDelete: boolean;
  onChange: (id: string, position: number, color?: string) => void;
  onDelete?: (id: string) => void;
}> = ({ stop, isDragging, canDelete, onChange, onDelete }) => {
  const [editingPos, setEditingPos] = useState<string | null>(null);

  const commitPosition = (raw: string) => {
    const num = parseInt(raw, 10);
    if (!isNaN(num)) {
      onChange(stop.id, Math.max(0, Math.min(1, num / 100)));
    }
    setEditingPos(null);
  };

  return (
    <div
      className={`flex items-center gap-1.5 group/row p-0.5 rounded-lg transition-colors ${isDragging ? "bg-white/5" : ""}`}
    >
      {/* Editable Position */}
      {editingPos !== null ? (
        <input
          type="number"
          min={0}
          max={100}
          autoFocus
          value={editingPos}
          onChange={(e) => setEditingPos(e.target.value)}
          onBlur={() => commitPosition(editingPos)}
          onKeyDown={(e) => {
            if (e.key === "Enter") commitPosition(editingPos);
            if (e.key === "Escape") setEditingPos(null);
          }}
          className="w-9 h-7 bg-white/10 border border-blue-500/50 rounded-lg text-[9px] font-bold text-white tabular-nums text-center outline-none [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
        />
      ) : (
        <button
          onClick={() => setEditingPos(String(Math.round(stop.position * 100)))}
          className="w-9 h-7 flex items-center justify-center bg-white/5 border border-white/10 rounded-lg text-[9px] font-bold text-neutral-400 tabular-nums hover:border-white/20 hover:text-neutral-300 transition-colors cursor-text"
        >
          {Math.round(stop.position * 100)}%
        </button>
      )}
      {/* Color Swatch (24×24) + Hex Label */}
      <label className="flex-1 flex items-center gap-1.5 h-7 px-2 bg-white/5 border border-white/10 rounded-lg hover:border-white/20 transition-colors cursor-pointer">
        <div className="relative w-6 h-6 rounded-md overflow-hidden border border-white/10 shrink-0 hover:ring-2 hover:ring-white/20 transition-all">
          <input
            type="color"
            value={stop.color}
            onChange={(e) => onChange(stop.id, stop.position, e.target.value)}
            className="absolute inset-[-6px] w-[calc(100%+12px)] h-[calc(100%+12px)] cursor-pointer"
          />
        </div>
        <span className="text-[10px] font-medium text-neutral-300 uppercase tabular-nums truncate">
          {stop.color.replace("#", "")}
        </span>
      </label>
      <button
        onClick={() => canDelete && onDelete?.(stop.id)}
        disabled={!canDelete}
        className="w-7 h-7 flex items-center justify-center text-neutral-500 hover:text-red-400 disabled:opacity-0 transition-colors"
      >
        <Trash2 size={12} />
      </button>
    </div>
  );
};

function useOnClickOutside(
  ref: React.RefObject<HTMLElement | null>,
  handler: (e: MouseEvent | TouchEvent) => void,
) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler(event);
    };
    document.addEventListener("mousedown", listener);
    document.addEventListener("touchstart", listener);
    return () => {
      document.removeEventListener("mousedown", listener);
      document.removeEventListener("touchstart", listener);
    };
  }, [ref, handler]);
}

