  const showToast = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const hasNonDefaultSettings = useCallback(() => {
    if (shaderParameters.length > 0) return true;
    return JSON.stringify(params) !== JSON.stringify(INITIAL_PARAMS);
  }, [params, shaderParameters]);

  const loadMediaFromItem = useCallback((item: any) => {
    const isVideo = item.type === 'video';
    const dataUrl = `data:${item.mimeType};base64,${item.base64}`;

    if (!isVideo) {
      setMedia({
        id: item.mediaId,
        base64: item.base64,
        mimeType: item.mimeType,
        dataUrl: dataUrl,
        type: 'image',
        name: item.name,
      });
      setMediaDims(null);
    } else {
      const bytes = Uint8Array.from(atob(item.base64), c => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: item.mimeType });
      const blobUrl = URL.createObjectURL(blob);

      setMedia({
        id: item.mediaId,
        base64: item.base64,
        mimeType: item.mimeType,
        dataUrl: blobUrl,
        type: 'video',
        name: item.name,
      });
      setMediaDims(null);
    }
  }, []);

  const applyReplace = useCallback((item: any) => {
    setParams(INITIAL_PARAMS);
    setShaderParameters([]);
    setMediaDims(null);
    setIsPlaying(true);
    setCurrentTime(0);
    setDuration(0);
    setVolume(0.5);
    setIsMuted(true);
    setIsSettingCenter(false);
    setLastEffect(ALL_EFFECTS[0]);
    isScrubbingRef.current = false;
    setVideoVersion((v) => v + 1);
    loadMediaFromItem(item);
    showToast('Settings reset & media replaced');
  }, [loadMediaFromItem]);

  const handleSelectMedia = async () => {
    try {
      const item = await Flow.media.select();
      if (!item) return;

      if (!media) {
        loadMediaFromItem(item);
        return;
      }

      if (hasNonDefaultSettings()) {
        setPendingReplaceItem(item);
        return;
      }

      applyReplace(item);
    } catch (err) {
      console.error('[Media Selection Error]', err);
    }
  };

  const confirmPendingReplace = () => {
    if (pendingReplaceItem) {
      applyReplace(pendingReplaceItem);
    }
    setPendingReplaceItem(null);
  };

  const cancelPendingReplace = () => {
    setPendingReplaceItem(null);
  };

  const handleResetAll = () => {
    setParams(INITIAL_PARAMS);
    showToast('All settings reset');
  };

  const performCleanRender = async (): Promise<string> => {
    if (!media || !mediaDims) throw new Error('No media loaded');

    const renderer = new OfflineRenderer(mediaDims.width, mediaDims.height, {
      intrinsicWidth: mediaDims.width,
      intrinsicHeight: mediaDims.height
    });
    try {
      await renderer.updateAssets(params.ascii.chars, params.gradientStops, params.presetId, shaderParameters);

      let source: TexImageSource;
      if (media.type === 'video' && videoRef.current) {
        const bridge = document.createElement('canvas');
        bridge.width = videoRef.current.videoWidth || mediaDims.width;
        bridge.height = videoRef.current.videoHeight || mediaDims.height;
        const bctx = bridge.getContext('2d', { alpha: false });
        if (!bctx) throw new Error('Failed to create bridge context');
        bctx.drawImage(videoRef.current, 0, 0, bridge.width, bridge.height);
        source = bridge;
      } else {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        await new Promise((resolve, reject) => {
          img.onload = resolve;
          img.onerror = reject;
          img.src = media.dataUrl;
        });
        source = img;
      }

      const time = media.type === 'video' ? (videoRef.current?.currentTime || 0) : 0;
      const canvas = renderer.renderFrame(source, params, time);
      return canvas.toDataURL('image/png');
    } finally {
      renderer.dispose();
    }
  };

  const handleCaptureFrame = async () => {
    if (!media || !mediaDims) return;
    setExportStatus('processing');

    try {
      const dataUrl = await performCleanRender();
      const base64 = dataUrl.split(',')[1];

      await Flow.save({
        base64,
        mimeType: 'image/png',
        name: `ShaderEffects-Capture-${Date.now()}`
      });

      showToast('Frame saved to gallery!');
    } catch (err) {
      console.error('[Capture Error]', err);
      showToast('Frame capture failed', 'error');
    } finally {
      setExportStatus('idle');
    }
  };

  const handleSave = async () => {
    if (!media || !mediaDims) return;

    setExportStatus('processing');
    setExportProgress(0);

    try {
      if (media.type === 'video') {
        const { buffer, plan } = await processVideo(media, params, shaderParameters, (p) => setExportProgress(p * 100));
        setExportPlan(plan);
        const base64 = arrayBufferToBase64(buffer);
        await Flow.save({
          base64,
          mimeType: plan.mimeType as 'video/mp4',
          name: `ShaderEffects-${Date.now()}`
        });
      } else {
        const dataUrl = await performCleanRender();
        const base64 = dataUrl.split(',')[1];
        await Flow.save({
          base64,
          mimeType: 'image/png',
          name: `ShaderEffects-${Date.now()}`
        });
      }

      setExportStatus('success');
      setTimeout(() => setExportStatus('idle'), 2000);
      showToast('Saved to gallery!');
    } catch (err) {
      console.error('[Export Error]', err);
      setExportStatus('idle');
      showToast('Export failed', 'error');
    }
  };

  const updateParam = <K extends keyof StudioParams>(key: K, value: StudioParams[K]) => {
    setParams(prev => ({ ...prev, [key]: value }));
  };

  const updatePresetParam = <P extends 'ascii' | 'dither', K extends keyof StudioParams[P]>(preset: P, key: K, value: StudioParams[P][K]) => {
    setParams(prev => ({
      ...prev,
      [preset]: {
        ...prev[preset],
        [key]: value
      }
    }));
  };

  const selectEffect = (effect: UnifiedEffect) => {
    setLastEffect(effect);
    setParams(prev => {
      const isActive = prev.presetId === effect.id;
      return { ...prev, presetId: isActive ? null : effect.id };
    });
  };

  const updateStop = (id: string, position: number, color?: string) => {
    setParams(prev => {
      const idx = prev.gradientStops.findIndex(s => s.id === id);
      if (idx === -1) return prev;

      const newStops = [...prev.gradientStops];
      newStops[idx] = { 
        ...newStops[idx], 
        position,
        ...(color !== undefined ? { color } : {})
      };

      return { ...prev, gradientStops: newStops, gradientId: null };
    });
  };

  const deleteStop = (id: string) => {
    setParams(prev => {
      if (prev.gradientStops.length <= 2) return prev;
      return {
        ...prev,
        gradientStops: prev.gradientStops.filter(s => s.id !== id),
        gradientId: null
      };
    });
  };

  const addStop = (position: number = 0.5) => {
    setParams(prev => {
      const sorted = [...prev.gradientStops].sort((a, b) => a.position - b.position);
      let newColor = '#ffffff';

      const afterIdx = sorted.findIndex(s => s.position >= position);
      if (afterIdx === -1) {
        newColor = sorted[sorted.length - 1].color;
      } else if (afterIdx === 0) {
        newColor = sorted[0].color;
      } else {
        const before = sorted[afterIdx - 1];
        const after = sorted[afterIdx];
        const range = after.position - before.position;
        const t = range > 0 ? (position - before.position) / range : 0.5;
        newColor = lerpHexColor(before.color, after.color, t);
      }

      return {
        ...prev,
        gradientStops: [...prev.gradientStops, { id: uid(), color: newColor, position }],
        gradientId: null,
      };
    });
  };

  const reverseGradient = () => {
    setParams(prev => ({
      ...prev,
      gradientStops: prev.gradientStops.map(s => ({ ...s, position: 1.0 - s.position })),
      gradientId: null,
    }));
  };

  const saveCustomTemplate = () => {
    const existingCustomIdx = customTemplates.findIndex(t => t.id === params.gradientId);
    if (existingCustomIdx !== -1) {
      setCustomTemplates(prev => {
        const next = [...prev];
        next[existingCustomIdx] = { ...next[existingCustomIdx], stops: cloneStops(params.gradientStops) };
        return next;
      });
      showToast('Template updated');
      return;
    }
    const id = `custom-${Date.now()}`;
    const newTpl: GradientTemplate = {
      id,
      name: `Custom ${customTemplates.length + 1}`,
      stops: cloneStops(params.gradientStops)
    };
    setCustomTemplates(prev => [...prev, newTpl]);
    updateParam('gradientId', id);
    showToast('New map saved');
  };

  const deleteCustomTemplate = (tplId: string) => {
    setCustomTemplates(prev => prev.filter(t => t.id !== tplId));
    if (params.gradientId === tplId) {
      updateParam('gradientId', null);
    }
  };

  const applyGradientTemplate = (tpl: GradientTemplate) => {
    setParams(prev => {
      if (prev.colorMode === 2 && prev.gradientId === tpl.id) {
        return { ...prev, colorMode: 1 };
      }
      return { ...prev, colorMode: 2, gradientId: tpl.id, gradientStops: cloneStops(tpl.stops) };
    });
  };

  const applyAsciiPreset = (presetName: string) => {
    const preset = ASCII_PRESETS.find(p => p.name === presetName);
    if (!preset) return;
    setParams(prev => ({
      ...prev,
      asciiPresetId: preset.id,
      ascii: {
        ...prev.ascii,
        chars: preset.chars,
        asciiFontSize: preset.asciiFontSize,
        charSpacing: preset.spacing
      }
    }));
  };

  const updateShaderParam = (index: number, value: ShaderParameterValue) => {
    setShaderParameters(prev => {
      const next = [...prev];
      next[index] = { ...next[index], value };
      return next;
    });
  };

  const handleCenterSet = useCallback((uv: THREE.Vector2) => {
    setShaderParameters(prev => prev.map(p => {
      if (p.name === 'u_center_x' || p.name === 'u_stable_x') return { ...p, value: Math.round(uv.x * 100) / 100 };
      if (p.name === 'u_center_y' || p.name === 'u_stable_y') return { ...p, value: Math.round(uv.y * 100) / 100 };
      return p;
    }));
    setIsSettingCenter(false);
    showToast('Center point updated');
  }, []);

  const handleCanvasReady = useCallback((canvas: HTMLCanvasElement) => { glCanvasRef.current = canvas; }, []);
  const handleShaderParametersChange = useCallback((newParams: ShaderParameter[]) => { setShaderParameters(newParams); }, []);
  const handleMediaLoad = useCallback((dims: { width: number, height: number }) => { setMediaDims(dims); }, []);
  const handleVideoReady = useCallback(() => { setVideoVersion(v => v + 1); }, []);

  const toggleShaderFilters = (enabled: boolean) => {
    if (!enabled) {
      setParams(prev => ({ ...prev, presetId: null }));
    } else {
      selectEffect(lastEffect);
    }
  };

  const handlePlayPause = () => {
    if (!videoRef.current) return;
    if (isPlaying) videoRef.current.pause();
    else videoRef.current.play();
  };

  const handleRestart = () => {
    if (!videoRef.current) return;
    videoRef.current.currentTime = 0;
    videoRef.current.play();
  };

  const handleSeekStart = () => { isScrubbingRef.current = true; };
  const handleSeekEnd = () => { isScrubbingRef.current = false; };
  const handleSeekChange = (time: number) => {
    setCurrentTime(time);
    if (videoRef.current) videoRef.current.currentTime = time;
  };

  const handleVolumeChange = (v: number) => {
    setVolume(v);
    if (v === 0) setIsMuted(true);
    else if (isMuted) setIsMuted(false);
  };

  const handleMuteToggle = () => {
    if (isMuted && volume === 0) setVolume(0.5);
    setIsMuted((m) => !m);
  };

  useEffect(() => {
    const v = videoRef.current;
    if (!v) return;
    v.volume = volume;
    v.muted = isMuted;
  }, [volume, isMuted, videoVersion]);

  return (
    <div className={`flex h-screen w-screen bg-[#0e0e0e] overflow-hidden select-none ${isSettingCenter ? 'center-setter-active' : ''}`}>
      {/* Left Sidebar */}
      <div
        className="shrink-0 h-full border-r border-[rgba(218,220,224,0.15)] bg-transparent transition-[width] duration-300 ease-in-out overflow-hidden"
        style={{ width: sidebarOpen ? 300 : 0 }}
      >
        <LeftSidebar
          params={params}
          media={media}
          shaderParameters={shaderParameters}
          allEffects={ALL_EFFECTS}
          isPlaying={isPlaying}
          isSettingCenter={isSettingCenter}
          videoRef={videoRef}
          onUpdatePresetParam={updatePresetParam}
          onSelectEffect={selectEffect}
          onToggleShaderFilters={toggleShaderFilters}
          onApplyAsciiPreset={applyAsciiPreset}
          onUpdateShaderParam={updateShaderParam}
          onSetIsSettingCenter={setIsSettingCenter}
        />
      </div>

      {/* Viewport */}
      <div className="relative flex-1 overflow-hidden flex items-center justify-center">
        {!media ? (
          <div className="text-center space-y-6 z-10 p-6 max-w-sm animate-in fade-in duration-700">
            <div className="mx-auto w-16 h-16 rounded-2xl bg-white/5 flex items-center justify-center border border-white/5 group transition-all">
              <Sparkles className="w-6 h-6 text-white/20 group-hover:text-white transition-colors" />
            </div>
            <div>
              <h2 className="text-xl font-bold tracking-tight mb-2">Choose Your Media</h2>
              <p className="text-neutral-500 text-sm leading-relaxed mb-8">
                Advanced media stylization pipeline with real-time WebGL processing.
              </p>
            </div>
            <PillButton 
              variant="filled" 
              icon={<ImagePlus size={18} strokeWidth={1.5} />} 
              onClick={handleSelectMedia} 
              className="mx-auto h-[42px] !pl-5 !pr-5 gap-2.5"
            >
              Import Content
            </PillButton>
          </div>
        ) : (
          <div className="relative z-10 w-full h-full flex items-center justify-center">
            <div
              style={{
                width: '100%',
                height: '100%',
              }}
            >
              <Canvas
                frameloop="demand"
                gl={{ 
                  preserveDrawingBuffer: true, 
                  antialias: false, 
                  powerPreference: 'high-performance',
                  alpha: true
                }}
                onCreated={({ gl: renderer }) => {
                  renderer.outputColorSpace = THREE.SRGBColorSpace;
                  renderer.toneMapping = THREE.NoToneMapping;
                }}
                camera={{ position: [0, 0, 1] }}
                style={{ width: '100%', height: '100%', display: 'block' }}
              >
                <StudioRenderer
                  key={media.id}
                  media={media}
                  params={params}
                  videoRef={videoRef}
                  shaderParameters={shaderParameters}
                  onShaderParametersChange={handleShaderParametersChange}
                  onCanvasReady={handleCanvasReady}
                  onMediaLoad={handleMediaLoad}
                  onVideoReady={handleVideoReady}
                  isSettingCenter={isSettingCenter}
                  onCenterSet={handleCenterSet}
                />
              </Canvas>
            </div>
          </div>
        )}

        {/* Center setter overlay */}
        {isSettingCenter && (
          <div className="absolute inset-0 z-50 pointer-events-none flex items-start justify-center pt-12">
            <div className="px-6 py-3 rounded-2xl bg-black/80 backdrop-blur-3xl border border-white/20 text-white shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-4 duration-300 pointer-events-auto">
              <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-white">
                <Crosshair size={18} className="animate-pulse" />
              </div>
              <div className="flex flex-col">
                <span className="text-xs font-bold uppercase tracking-widest">Select Center</span>
                <span className="text-[10px] text-neutral-400">Click anywhere on the preview</span>
              </div>
              <button 
                onClick={() => setIsSettingCenter(false)}
                className="ml-4 p-2 rounded-lg hover:bg-white/10 transition-colors"
              >
                <X size={16} />
              </button>
            </div>
          </div>
        )}

        {/* Video transport */}
        {media?.type === 'video' && (
          <VideoTransport
            isPlaying={isPlaying}
            currentTime={currentTime}
            duration={duration}
            volume={volume}
            isMuted={isMuted}
            onPlayPause={handlePlayPause}
            onRestart={handleRestart}
            onSeekStart={handleSeekStart}
            onSeekEnd={handleSeekEnd}
            onSeekChange={handleSeekChange}
            onVolumeChange={handleVolumeChange}
            onMuteToggle={handleMuteToggle}
          />
        )}

        {/* Toast */}
        {toast && (
          <div className="absolute top-24 left-1/2 -translate-x-1/2 z-[100] px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-2xl backdrop-blur-2xl bg-white text-black transition-all animate-in slide-in-from-top-4">
            {toast.message}
          </div>
        )}
      </div>

      {/* Sidebar toggle */}
      <button
        onClick={() => setSidebarOpen(p => !p)}
        className="absolute top-4 z-30 w-8 h-8 flex items-center justify-center rounded-lg bg-black/40 backdrop-blur-md border border-white/10 text-white/60 hover:text-white hover:bg-black/60 transition-all duration-300 ease-in-out"
        style={{ right: sidebarOpen ? 312 : 12 }}
        title={sidebarOpen ? 'Collapse panel' : 'Expand panel'}
      >
        {sidebarOpen ? <PanelRightClose size={16} /> : <PanelRightOpen size={16} />}
      </button>

      {/* Sidebar */}
      <div 
        className="shrink-0 h-full border-l border-[rgba(218,220,224,0.15)] bg-transparent transition-[width] duration-300 ease-in-out overflow-hidden flex flex-col"
        style={{ width: sidebarOpen ? 300 : 0 }}
      >
        <div className="flex-1 overflow-hidden">
          <Sidebar
            params={params}
            media={media}
            customTemplates={customTemplates}
            exportStatus={exportStatus}
            exportProgress={exportStatusProgress}
            onUpdateParam={updateParam}
            onSelectMedia={handleSelectMedia}
            onResetAll={handleResetAll}
            onUpdateStop={updateStop}
            onDeleteStop={deleteStop}
            onAddStop={addStop}
            onReverseGradient={reverseGradient}
            onApplyGradientTemplate={applyGradientTemplate}
            onSaveCustomTemplate={saveCustomTemplate}
            onDeleteCustomTemplate={deleteCustomTemplate}
            onCaptureFrame={handleCaptureFrame}
            onSave={handleSave}
          />
        </div>
        {/* Export Readout */}
        {sidebarOpen && media?.type === 'video' && exportPreviewPlan && (
          <div className="px-[10px] pb-4">
            <div className="text-[10px] font-mono uppercase tracking-[0.1em] text-neutral-500 opacity-60 text-center">
              {formatBitrateLabel(exportPreviewPlan)}
            </div>
          </div>
        )}
      </div>

      {/* Export overlay */}
      {exportStatus === 'processing' && (
        <ExportOverlay progress={exportStatusProgress} plan={exportPlan} />
      )}

      {/* Replace-media confirmation dialog */}
      {pendingReplaceItem && (
        <div
          className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200"
          onClick={cancelPendingReplace}
        >
          <div
            className="w-[360px] rounded-2xl bg-[#1a1a1a] border border-white/10 shadow-2xl p-6 flex flex-col gap-4 animate-in zoom-in-95 duration-200"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex flex-col gap-2">
              <h3 className="text-base font-bold tracking-tight text-white">
                Replace media?
              </h3>
              <p className="text-sm text-neutral-400 leading-relaxed">
                This will reset all filter settings and parameters. Your saved gradient maps will be kept.
              </p>
            </div>
            <div className="flex gap-2 justify-end pt-2">
              <PillButton
                variant="solid"
                onClick={cancelPendingReplace}
                className="px-5 h-[36px] !pl-5 !pr-5"
              >
                Cancel
              </PillButton>
              <PillButton
                variant="filled"
                onClick={confirmPendingReplace}
                className="px-5 h-[36px] !pl-5 !pr-5"
              >
                Replace & Reset
              </PillButton>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import {
  getFirstEncodableVideoCodec,
  Mp4OutputFormat,
  WebMOutputFormat,
  type VideoCodec,
} from "mediabunny";

export type ExportPlan = {
  codec: VideoCodec;
  container: 'mp4' | 'webm';
  mimeType: 'video/mp4' | 'video/webm';
  extension: 'mp4' | 'webm';
  bitrate: number;
  width: number;
  height: number;
  fps: number;
};

const PREFERRED_CODECS: VideoCodec[] = ['avc', 'vp9', 'av1', 'vp8'];

const CONTAINER_BY_CODEC: Record<VideoCodec, 'mp4' | 'webm'> = {
  avc:  'mp4',
  hevc: 'mp4',
  av1:  'mp4',
  vp9:  'webm',
  vp8:  'webm',
};

/**
 * Computes the target bitrate based on resolution, frame rate, and effect type.
 * Uses a "Bits Per Pixel" (BPP) calculation to ensure quality scales with size.
 */
export function computeBitrate(opts: {
  width: number;
  height: number;
  fps: number;
  presetId: string | null;
  grain: number;
}): number {
  // High-frequency effects like ASCII and Dither, or added Film Grain, 
  // require significantly more bandwidth to prevent the encoder from 
  // smoothing out the intended "noise" or sharp character edges.
  const isHighFrequency = opts.presetId === 'ascii' || opts.presetId === 'dither' || opts.grain > 0.05;

  // Updated BPP and Floor based on user request:
  // For high-frequency details (Grain, ASCII, Dither): BPP = 0.8, Min = 50Mbps
  // For standard filters: BPP = 0.35, Min = 20Mbps
  const BPP = isHighFrequency ? 0.8 : 0.35;
  const minBitrate = isHighFrequency ? 50_000_000 : 20_000_000;

  const computed = Math.round(opts.width * opts.height * opts.fps * BPP);

  // Cap at 200Mbps to avoid excessive file sizes while maintaining ultra-high fidelity.
  return Math.max(minBitrate, Math.min(200_000_000, computed));
}

export async function planExport(opts: {
  width: number;
  height: number;
  fps: number;
  presetId: string | null;
  grain: number;
}): Promise<ExportPlan> {
  const bitrate = computeBitrate(opts);
  const codec = await getFirstEncodableVideoCodec(PREFERRED_CODECS, {
    width: opts.width,
    height: opts.height,
    bitrate,
  });

  if (!codec) {
    throw new Error('No browser-encodable video codec available');
  }

  const container = CONTAINER_BY_CODEC[codec];

  return {
    codec,
    container,
    mimeType: container === 'mp4' ? 'video/mp4' : 'video/webm',
    extension: container,
    bitrate,
    width: opts.width,
    height: opts.height,
    fps: opts.fps,
  };
}

export function buildOutputFormat(plan: ExportPlan) {
  return plan.container === 'mp4'
    ? new Mp4OutputFormat({ fastStart: 'in-memory' })
    : new WebMOutputFormat({});
}

export function formatBitrateLabel(plan: ExportPlan): string {
  const mbps = (plan.bitrate / 1_000_000).toFixed(1).replace(/\.0$/, '');
  const codecLabel =
    plan.codec === 'avc' ? 'H.264' :
    plan.codec === 'hevc' ? 'H.265' :
    plan.codec === 'vp9' ? 'VP9' :
    plan.codec === 'vp8' ? 'VP8' :
    'AV1';

  return `${plan.width}×${plan.height} · ${codecLabel} · ~${mbps} Mbps · ${plan.fps} fps`;
}
